\section{Definition of abelian varieties}
\label{mumford-source-II4}
\dcref{M:ch2:II.4}

\begin{definition}[Abelian variety]
\label{mumford-def-abelian-variety}
\dcref{M:ch2:II.4}
An abelian variety $X$ is a complete algebraic variety over an algebraically
closed field $k$ with a group law $m:X\times X\to X$ such that $m$ and the
inverse map are morphisms of varieties.
\source{mumford-abelian-varieties:page-0050}\source{mumford-abelian-varieties:page-0051}
\end{definition}

\begin{proposition}[Basic structure]
\label{mumford-source-basic-structure}
\dcref{M:ch2:II.4}
If $g=\dim X$, then
\[
 X_n\simeq(\mathbf Z/n\mathbf Z)^{2g}\quad(\operatorname{char}k\nmid n),
 \qquad X_{p^m}\simeq(\mathbf Z/p^m\mathbf Z)^i
\]
for $p=\operatorname{char}k$, where $0\le i\le g$; $X$ is commutative and
divisible. Moreover
\[
 H^q(X,\Omega^p)\simeq\bigwedge^p H^1(X,\Omega^1)\otimes_k
 \bigwedge^q H^1(X,\mathcal O_X),
\quad \dim H^1(X,\mathcal O_X)=\dim H^0(X,\Omega^1)=g.
\]
\source{mumford-abelian-varieties:page-0050}
\end{proposition}

\begin{lemma}[Translations]
\label{mumford-lem-abelian-translations}
\dcref{M:ch2:II.4}
For every $a\in X$, the translation $T_a(x)=a+x$ is an automorphism of $X$;
its inverse is $T_{-a}$.  Consequently, local geometric properties are
preserved by translation.
\source{mumford-abelian-varieties:page-0052}\source{mumford-abelian-varieties:page-0053}
\uses{mumford-def-abelian-variety}
\end{lemma}
\begin{proof}
The group identities give $T_{-a}\circ T_a=T_a\circ T_{-a}=\operatorname{id}$,
and both maps are morphisms because the group law and inverse are morphisms.
\end{proof}

\begin{proposition}[Fundamental group and free finite quotients]
\label{mumford-source-II4-roadmap}
\dcref{M:ch2:II.4}
If $g=\dim X$ and $p=\operatorname{char}k$, then the algebraic fundamental group
has the expected form
\[
 \pi_1(X)\simeq\prod_\ell(\mathbf Z_\ell)^{2g}\quad(p=0),\qquad
 \pi_1(X)\simeq\prod_{\ell\ne p}(\mathbf Z_\ell)^{2g}\times\mathbf Z_p^i
 \quad(p>0),
\]
where $i$ is the $p$-rank.  More generally, if a finite group acts freely on a
variety $Y$ with quotient $X$, then some $n>0$ and homomorphisms fit into
\[
\begin{array}{ccccc}&&Y&&\\[-2pt]&\swarrow&&\searrow&\\[-2pt]
X&&\xrightarrow{\,n_X\,}&&X.
\end{array}
\]
The variety $Y$ carries an abelian-variety structure for which both maps are
homomorphisms.
\source{mumford-abelian-varieties:page-0050}\source{mumford-abelian-varieties:page-0051}

\notready
\end{proposition}

\begin{lemma}[Everywhere nonsingular]
\label{mumford-source-nonsingular}
\dcref{M:ch2:II.4}
An abelian variety is everywhere nonsingular.
\source{mumford-abelian-varieties:page-0052}
\end{lemma}
\begin{proof}
There is a nonsingular point $x_0$. For $x\in X$, the translation morphism
$T_{(x,x_0^{-1})}(y)=x\cdot x_0^{-1}\cdot y$ is an automorphism carrying
$x_0$ to $x$, so $x$ is nonsingular.
\end{proof}

\begin{theorem}[First commutativity proof]
\label{mumford-source-commutativity-I}
\dcref{M:ch2:II.4}
An abelian variety is commutative.
\source{mumford-abelian-varieties:page-0052}
\end{theorem}
\begin{proof}
For $x\in X$, conjugation $C_x(y)=xyx^{-1}$ induces an automorphism
$C^*_{x,n}$ of $\mathcal O_{X,e}/\mathfrak m_{X,e}^n$. The map
$X\to\operatorname{Aut}(\mathcal O_{X,e}/\mathfrak m_{X,e}^n)$ is a morphism
to an affine variety, hence constant because $X$ is complete and connected.
It equals the identity at $e$. Thus $C^*_{x,n}=1$ for every $n$; since
$\bigcap_n\mathfrak m_{X,e}^n=0$, $C_x$ is the identity near $e$, hence on
the irreducible variety $X$.
\end{proof}

We write the group law additively. Let $T_x(y)=x+y$ and let $n_X$ denote
multiplication by $n$.
\source{mumford-abelian-varieties:page-0052}\source{mumford-abelian-varieties:page-0053}

\begin{proposition}[Invariant differentials]
\label{mumford-source-invariant-differentials}
\dcref{M:ch2:II.4}
If $T=T_{X,0}$ and $\Omega_0=T^*_{X,0}$, then
\[
 \Omega_0\otimes_k\mathcal O_X\xrightarrow{\sim}\Omega_X^1.
\]
Every regular differential form on $X$ is translation invariant.
\source{mumford-abelian-varieties:page-0053}
\end{proposition}
\begin{proof}
For $\theta\in\Omega_0$, define $\omega_\theta$ by
$(\omega_\theta)_x=T^*_{-x}(\theta)$. This is regular and gives the map.
At each $x$, $T^*_{-x}$ identifies the fiber with $\Omega_0$, so Nakayama's
lemma proves it is an isomorphism. Since $H^0(X,\mathcal O_X)=k$, the claim
about global forms follows.
\end{proof}

\begin{theorem}[Prime-to-characteristic multiplication]
\label{mumford-prop-multiplication-n}
\dcref{M:ch2:II.4}
For every $n$ not divisible by $\operatorname{char}k$, $n_X$ is surjective.
\source{mumford-abelian-varieties:page-0053}\source{mumford-abelian-varieties:page-0054}
\end{theorem}
\begin{proof}
The tangent space at $(0,0)$ splits as $T\oplus T$, and the differential of
$m$ is addition: $d(m)(t_1,t_2)=t_1+t_2$, since the restrictions to the two
summands are the identity. Induction gives $(dn_X)_0=n$ on $T$. Thus it is an
isomorphism when $\operatorname{char}k\nmid n$. If $n_X$ were not surjective,
the dimension theorem would give a nonzero tangent vector to
$n_X^{-1}(0)$ at $0$, contradicting injectivity of $(dn_X)_0$.
\end{proof}

\begin{lemma}[Rigidity Lemma, Form I]
\label{mumford-lem-rigidity-form-I}
\lean{Mumford.GroupScheme.rigidity_lemma_of_geometricallyIntegral}
\dcref{M:ch2:II.4}
Let $X$ be complete, $Y,Z$ varieties, and $f:X\times Y\to Z$ a morphism such
that $f(X\times\{y_0\})=\{z_0\}$. Then $f=g\circ p_2$ for a morphism
$g:Y\to Z$.
\source{mumford-abelian-varieties:page-0054}
\leanok
\end{lemma}
\begin{proof}
Choose $x_0\in X$ and set $g(y)=f(x_0,y)$. Let $U$ be an affine neighborhood
of $z_0$, $F=Z-U$, and $G=p_2(f^{-1}(F))$. Since $X$ is complete, $G$ is
closed; since $y_0\notin G$, $V=Y-G$ is nonempty open. For $y\in V$, the
complete variety $X\times\{y\}$ maps into affine $U$, hence to one point.
Thus $f(x,y)=f(x_0,y)=g(p_2(x,y))$ on a nonempty open, and therefore everywhere.
\leanok
\end{proof}

\begin{corollary}[Morphisms are homomorphisms up to translation]
\label{mumford-cor-morphism-translation}
\dcref{M:ch2:II.4}
If $X,Y$ are abelian varieties and $f:X\to Y$ is a morphism, then
$f(x)=h(x)+a$ for a homomorphism $h$ and $a\in Y$.
\source{mumford-abelian-varieties:page-0054}
\lean{Mumford.GroupScheme.exists_hom_comp_pointTranslation_of_isAbelianVariety_arbitraryField}
\leanok
\uses{mumford-lem-rigidity-form-I}
\end{corollary}
\begin{proof}
Replace $f$ by $f-f(0)$. The morphism
$\phi(x,y)=f(x+y)-f(y)-f(x)$ vanishes on both coordinate axes. Rigidity gives
$\phi=0$, so $f$ is a homomorphism.
\end{proof}

\begin{corollary}[Second commutativity proof]
\label{mumford-cor-abelian-commutative}
\dcref{M:ch2:II.4}
An abelian variety is commutative.
\source{mumford-abelian-varieties:page-0055}
\lean{Mumford.GroupScheme.isCommMonObj_of_isAbelianVariety_via_rigidity}
\leanok
\uses{mumford-cor-morphism-translation}
\end{corollary}
\begin{proof}
The inverse map is a homomorphism by the preceding corollary. Hence
$(xy)^{-1}=x^{-1}y^{-1}=y^{-1}x^{-1}$, so $X$ is commutative.
\end{proof}

\begin{corollary}[Linearity of maps into an abelian variety]
\label{mumford-cor-pointed-hom-linear}
\dcref{M:ch2:II.4}
For pointed complete varieties $S,T$ and an abelian variety $X$,
\[
 \Hom(S,X)\times\Hom(T,X)\xrightarrow{\sim}\Hom(S\times T,X),
 \qquad(f,g)\mapsto[(s,t)\mapsto f(s)+g(t)].
\]
\source{mumford-abelian-varieties:page-0055}
\lean{Mumford.GroupScheme.pointedProductHomEquiv}
\leanok
\uses{mumford-lem-rigidity-form-I}
\end{corollary}
\begin{proof}
Injectivity follows by setting either variable equal to its base point. Given
$h$, set $f(s)=h(s,t_0)$, $g(t)=h(s_0,t)$ and
$k(s,t)=h(s,t)-f(s)-g(t)$. Rigidity applied to $k$ gives $k=0$.
\end{proof}

\begin{theorem}[Recognition criterion]
\label{mumford-thm-unital-composition}
\dcref{M:ch2:II.4}
Let $X$ be complete, $e\in X$, and $m:X\times X\to X$ satisfy
$m(x,e)=m(e,x)=x$. Then $m$ is an abelian-variety group law with identity $e$.
\source{mumford-abelian-varieties:page-0055}\source{mumford-abelian-varieties:page-0056}
\end{theorem}
\begin{proof}
Write $xy=m(x,y)$ and define $\psi(x,y)=(xy,y)$. Since
$\psi^{-1}(e,e)=\{(e,e)\}$, the dimension theorem and completeness make
$\psi$ surjective. Let $\Gamma'$ be $\{(x,y):xy=e\}$, choose an irreducible
component $\Gamma$ projecting onto the second factor, and then onto the first
factor by the dimension theorem. Rigidity applied to
$\phi((x',x),y)=x'(xy)$ gives
\[
 x'(xy)=y\quad((x',x)\in\Gamma).
 \tag{1}
\]
Choosing $(x'',x')\in\Gamma$ and using (1) shows also $xx'=e$.

Apply rigidity to $\chi(((x',x),y,z))=x'((xy)z)$ to obtain
$x'((xy)z)=yz$. Multiplying on the left by $x'$ and using (1) gives
$(x'y)z=x'(yz)$. Since $x'$ is arbitrary, multiplication is associative.
Translations are then automorphisms, so $X$ is nonsingular; $\psi$ is
bijective. Its tangent map at $(e,e)$ is an isomorphism, so it is inseparable
and, by Zariski's Main Theorem, an isomorphism. Its inverse is
$(x,y)\mapsto(xy^{-1},y)$, proving that inversion is a morphism.
\end{proof}

\section{Cohomology and base change}
\label{mumford-source-II5}
\dcref{M:ch2:II.5}

\begin{theorem}[Coherence of proper direct images]
\label{mumford-thm-proper-direct-image-coherent}
\dcref{M:ch2:II.5}
If $f:X\to Y$ is proper between locally noetherian preschemes and $\mathcal F$
is coherent, then $R^pf_*\mathcal F$ is coherent for all $p\ge0$.
\source{mumford-abelian-varieties:page-0057}

\notready
\end{theorem}

\begin{definition}[Flat over the base]
\label{mumford-def-f-flat}
\dcref{M:ch2:II.5}
A quasicoherent $\mathcal F$ on $X$ is $f$-flat if every $\mathcal F_x$ is
$\mathcal O_{Y,f(x)}$-flat; equivalently, sections over affine $U$ mapping into
affine $V$ are flat $\mathcal O_Y(V)$-modules.
\source{mumford-abelian-varieties:page-0057}
\end{definition}

\begin{theorem}[Cohomology and base change complex]
\label{mumford-thm-grothendieck-complex}
\dcref{M:ch2:II.5}
For proper $f:X\to Y$ with $Y=\Spec A$, $X$ noetherian, and coherent
$\mathcal F$ flat over $Y$, there is a finite complex $K^\bullet$ of finitely generated
projective $A$-modules such that, functorially for every $A$-algebra $B$,
\[
 H^p(X\times_Y\Spec B,\mathcal F\otimes_A B)
 \simeq H^p(K^\bullet\otimes_A B).
\]
\source{mumford-abelian-varieties:page-0057}\source{mumford-abelian-varieties:page-0058}\source{mumford-abelian-varieties:page-0059}\source{mumford-abelian-varieties:page-0060}
\end{theorem}
\begin{proof}
Choose a finite affine covering and its Cech complex $C^\bullet$. It is a
finite complex of flat $A$-modules and base change identifies its cohomology
with the fiber cohomology. Lemma~\ref{mumford-source-complex-model} supplies
a finite complex $K^\bullet$ of finite modules, free in positive degrees,
quasi-isomorphic to $C^\bullet$, with $K^0$ flat. Since $A$ is noetherian,
$K^0$ is projective.

For completeness, the construction descends on $m$: choose a free module
mapping onto the kernel of $\ker\partial^{m+1}\to H^{m+1}(C^\bullet)$ and a
free module mapping onto $H^m(C^\bullet)$, lift the latter to cycles, and
take their direct sum. At $m=-1$ quotient $K^0$ by
$\ker\partial^0\cap\ker\phi_0$. The mapping cylinder
$L^p=K^p\oplus C^{p-1}$ is exact; if all $C^p$ are flat, the short exact
sequences $0\to Z^p\to L^p\to Z^{p+1}\to0$ show $K^0=L^0$ is flat.

Lemma~\ref{mumford-lem-flat-quasi-iso-base-change} applied to $K^\bullet\to C^\bullet$
shows that base change preserves the quasi-isomorphism, proving the claim.
\end{proof}

\begin{lemma}[Finite complex model]
\label{mumford-source-complex-model}
\dcref{M:ch2:II.5}
Let $C^\bullet$ be bounded over a noetherian ring $A$, with finitely generated
cohomology. There is a bounded complex $K^\bullet$ of finite modules, free in
positive degrees, mapping quasi-isomorphically to $C^\bullet$; if $C^p$ are
flat, $K^0$ is flat.
\source{mumford-abelian-varieties:page-0058}\source{mumford-abelian-varieties:page-0059}\source{mumford-abelian-varieties:page-0060}
\end{lemma}
\begin{proof}
Construct $K^\bullet$ by descending induction. Put $K^p=0$ for $p>n$.
Assume the maps have been constructed above degree $m$ so that they induce
cohomology isomorphisms above degree $m+1$ and a surjection
$\ker\partial^{m+1}\to H^{m+1}(C^\bullet)$. For $m\ge0$, let
$B^{m+1}$ be the kernel of this surjection. Choose a finite free ${K'}^m$
surjecting onto $B^{m+1}$, and a finite free ${K''}^m$ surjecting onto
$H^m(C^\bullet)$; lift the latter map to cycles. Set
$K^m={K'}^m\oplus{K''}^m$, let the differential vanish on ${K''}^m$ and
map ${K'}^m$ onto $B^{m+1}$, and lift this map to $C^m$. The resulting map
of complexes has the required cohomology properties. For $m=-1$, replace
$K^0$ by $K^0/(\ker\partial^0\cap\ker\phi_0)$.

If all $C^p$ are flat, form the mapping cylinder
$L^p=K^p\oplus C^{p-1}$ with
$\partial(x,0)=(\partial x,\phi(x))$ and
$\partial(0,y)=(0,-\partial y)$. The exact sequence of complexes with the
shifted $C^\bullet$ shows $H^p(L^\bullet)=0$. Hence
$0\to K^0=L^0\to L^1\to\cdots\to L^{n+1}\to0$ is exact; its other terms
are flat, so $K^0$ is flat.
\end{proof}

\begin{lemma}[Flat complexes commute with arbitrary base change]
\label{mumford-lem-flat-quasi-iso-base-change}
\dcref{M:ch2:II.5}
If finite complexes of flat $A$-modules are quasi-isomorphic, then their
cohomologies remain isomorphic after tensoring with every $A$-algebra $B$.
\source{mumford-abelian-varieties:page-0060}
\end{lemma}
\begin{proof}
Construct the mapping cylinder $L^\bullet$ of the quasi-isomorphism. It is an
exact finite complex of flat modules. Its cycles $Z^p$ are flat, and
\[
0\to Z^p\to L^p\to Z^{p+1}\to0
\]
is exact. Tensoring with $B$ remains exact, so $L^\bullet\otimes_A B$ is
exact. It is the mapping cylinder after base change; the cohomology sequence
therefore gives the required isomorphisms.
\end{proof}

\begin{corollary}[Semicontinuity and Euler characteristic]
\label{mumford-thm-semicontinuity}
\dcref{M:ch2:II.5}
For proper $f:X\to Y$ and coherent $\mathcal F$ flat over $Y$, the function
$y\mapsto\dim_{k(y)}H^p(X_y,\mathcal F_y)$ is upper semicontinuous, while
$y\mapsto\chi(\mathcal F_y)$ is locally constant.
\source{mumford-abelian-varieties:page-0061}
\end{corollary}
\begin{proof}
Locally choose the free complex $K^\bullet$ and write $d^p:K^p\to K^{p+1}$.
Then
\[
\dim H^p=\dim K^p\otimes k(y)-\dim\operatorname{Im}(d^p\otimes k(y))
 -\dim\operatorname{Im}(d^{p-1}\otimes k(y)).
\]
The alternating sum is locally constant. The image rank is lower
semicontinuous because its rank-drop locus is cut out by the entries of the
induced exterior-power matrix, proving upper semicontinuity.
\end{proof}

\begin{corollary}[Base-change criterion]
\label{mumford-thm-base-change-criterion}
\dcref{M:ch2:II.5}
If $Y$ is reduced and connected, constancy of
$y\mapsto\dim H^p(X_y,\mathcal F_y)$ is equivalent to $R^pf_*\mathcal F$
being locally free and having fibers $H^p(X_y,\mathcal F_y)$. Under these
conditions the same base-change map is an isomorphism in degree $p-1$.
\source{mumford-abelian-varieties:page-0061}\source{mumford-abelian-varieties:page-0062}\source{mumford-abelian-varieties:page-0063}
\end{corollary}
\begin{proof}
First, on a reduced scheme, a coherent sheaf with constant fiber dimension
$r$ is locally free of rank $r$: lift generators at a point, apply Nakayama,
and observe that the kernel lies in $\mathfrak m_y\mathcal O_y^r$ at every
point, hence vanishes on a reduced scheme. Second, if
$\phi:\mathscr F\to\mathfrak D$ is a map of locally free sheaves with
locally constant image rank, the preceding result makes the cokernel locally
free. Thus the image is projective and both source and target split, with
matrix $\left[\begin{smallmatrix}0&\text{isom.}\\0&0\end{smallmatrix}\right]$.
Applying the splitting to $d_{p-1}$ and $d_p$ in $K^\bullet$ gives projective
modules $B_p,H_p,K'_p$ with
$B_p\oplus H_p=\ker d_p$ and $d_p:K'_p\simeq B_{p+1}$. Hence
$H^p(K^\bullet\otimes B)=H_p\otimes B=H^p(K^\bullet)\otimes B$ and likewise
in degree $p-1$.
\end{proof}

\begin{corollary}[Vanishing in the preceding degree]
\label{mumford-source-base-change-vanishing}
\dcref{M:ch2:II.5}
If $H^p(X_y,\mathcal F_y)=0$ for all $y$, then
$R^{p-1}f_*\mathcal F\otimes k(y)\simeq H^{p-1}(X_y,\mathcal F_y)$ for all $y$.
\source{mumford-abelian-varieties:page-0064}
\end{corollary}
\begin{proof}
Locally write the relevant part of $K^\bullet$ as
$K^{p-1}\to K^p\to K^{p+1}$. Exactness after tensoring with $k(y)$ permits
a splitting $K^p\otimes k(y)=\overline W_1\oplus\overline W_2$, where the
first summand is the image and the second maps injectively. After localizing
at a function nonzero at $y$, lift bases to a splitting $K^p=W_1\oplus W_2$
with $W_1\subset\operatorname{Im}d^{p-1}$; injectivity on $W_2$ persists,
so $W_1=\operatorname{Im}d^{p-1}$. The surjection onto $W_1$ splits, giving
$K^{p-1}=\ker d^{p-1}\oplus W_1$ and exact sequences
\[
 K^{p-2}\to\ker d^{p-1}\to H^{p-1}(X,\mathcal F)\to0,
\quad
 K^{p-2}\otimes k(y)\to\ker d^{p-1}\otimes k(y)\to
 H^{p-1}(X_y,\mathcal F_y)\to0.
\]
This proves the asserted base-change isomorphism.
\end{proof}

\begin{corollary}[Higher vanishing]
\label{mumford-source-higher-vanishing}
\dcref{M:ch2:II.5}
If $R^kf_*\mathcal F=0$ for $k>k_0$, then $H^k(X_y,\mathcal F_y)=0$ for
$k>k_0$ and all $y$.
\source{mumford-abelian-varieties:page-0064}
\end{corollary}
\begin{proof}
Apply the preceding vanishing-in-the-preceding-degree corollary and use
decreasing induction on $k_0$.
\end{proof}

\begin{corollary}[Flat base change]
\label{mumford-cor-flat-base-change}
\dcref{M:ch2:II.5}
If $B$ is flat over $A$, then
\[
 H^p(X\times_Y\Spec B,\mathcal F\otimes_A B)\simeq H^p(X,\mathcal F)\otimes_A B.
\]
\source{mumford-abelian-varieties:page-0064}\source{mumford-abelian-varieties:page-0065}
\end{corollary}
\begin{proof}
For a flat algebra, cohomology of any complex commutes with tensor product.
\end{proof}

\begin{theorem}[Seesaw theorem, provisional form]
\label{mumford-thm-seesaw}
\dcref{M:ch2:II.5}
For complete $X$, any variety $T$, and a line bundle $L$ on $X\times T$, the
set of $t$ for which $L|_{X\times\{t\}}$ is trivial is closed. On this closed
set $T_1$, $L|_{X\times T_1}\simeq p_2^*M$ for a line bundle $M$ on $T_1$.
\source{mumford-abelian-varieties:page-0065}\source{mumford-abelian-varieties:page-0066}
\uses{mumford-thm-base-change-criterion}
\end{theorem}
\begin{proof}
A line bundle $M$ on complete $X$ is trivial iff both $H^0(X,M)$ and
$H^0(X,M^{-1})$ are nonzero: dual nonzero sections compose to a nonzero
constant, giving inverse isomorphisms. Thus $T_1$ is the intersection of the
two closed loci supplied by semicontinuity. After replacing $T$ by $T_1$,
all fibers are trivial and have one-dimensional $H^0$. Base-change criterion
gives $p_{2*}\underline L=\underline M$ invertible and the natural map
$p_2^*\underline M\to\underline L$ is an isomorphism.
\end{proof}

\section{The theorem of the cube: I}
\label{mumford-source-II6}
\dcref{M:ch2:II.6}

\begin{theorem}[Theorem of the cube]
\label{mumford-thm-cube-varieties}
\dcref{M:ch2:II.6}
Let $X,Y$ be complete varieties, $Z$ any variety, with base points
$x_0,y_0,z_0$. If a line bundle $L$ on $X\times Y\times Z$ restricts
trivially to each of $\{x_0\}\times Y\times Z$,
$X\times\{y_0\}\times Z$, and $X\times Y\times\{z_0\}$, then $L$ is trivial.
\source{mumford-abelian-varieties:page-0066}

\end{theorem}

\begin{remark}[Functorial order]
\label{mumford-source-functor-order}
\dcref{M:ch2:II.6}
For a contravariant functor $T$ on complete varieties, define projections
$\pi_i$ and base-point inclusions $\sigma_i$ by omitting and restoring the
$i$th factor. Then
\[
 \alpha_T^n(\xi_0,\ldots,\xi_n)=\sum_{i=0}^n\pi_i^*(\xi_i),
 \qquad
 \beta_T^n(\eta)=(\sigma_0^*\eta,\sigma_2^*\eta,\ldots,\sigma_n^*\eta),
\]
and induction gives $T(\prod X_i)=\operatorname{Im}\alpha\oplus\ker\beta$.
The functor has order $n$ when $\alpha$ is surjective (equivalently $\beta$
injective). The cube theorem, when $Z$ is complete, says that $\Pic X$ is
quadratic.
\source{mumford-abelian-varieties:page-0066}
\end{remark}




\begin{proof}[Proof of the theorem (following Weil and Murre)]
\label{mumford-proof-theorem-of-the-cube}
\dcref{M:ch2:II.6}
\source{mumford-abelian-varieties:page-0067}
\source{mumford-abelian-varieties:page-0068}
\source{mumford-abelian-varieties:page-0069}
\source{mumford-abelian-varieties:page-0070}
By the Seesaw theorem, it is sufficient to prove that for every
$(x,z)\in X\times Z$, the restriction of $L$ to
$\{x\}\times Y\times\{z\}$ is trivial, since it is already given that
$L|_{X\times\{y_0\}\times Z}$ is trivial.
\end{proof}

\begin{lemma}
\label{mumford-lem-cube-curve-joining}
\dcref{M:ch2:II.6}
Let $X$ be any variety and $x_0,x_1\in X$. Then there is an irreducible
curve $C$ on $X$ containing $x_0$ and $x_1$.
\end{lemma}
\begin{proof}
Assume $\dim X>1$. By Chow's lemma, we may assume $X$ projective. By induction
on $\dim X$, it is sufficient to find a subvariety of codimension one
containing $x_0$ and $x_1$. Choose a birational $f:X'\to X$ with $X'$ projective
and $\dim f^{-1}(x_i)\ge1$. If $X'\subset\mathbf P^N$, Bertini gives a
hyperplane $H$ for which $Y'=H\cap X'$ is irreducible, and
$H\cap f^{-1}(x_i)\ne\varnothing$. Then $Y=f(Y')$ is irreducible and contains
$x_0,x_1$.
\end{proof}

\begin{proof}[Proof of the theorem (continued)]
For any $x\in X$, choose an irreducible complete curve $C_1$ joining $x_0$ to
$x$. Let $\pi:C\to C_1$ be its normalization, and let
\(\pi':C\times Y\times Z\to X\times Y\times Z\) be induced. The hypotheses
remain true for \(\pi'^*L\), and it is enough to prove its triviality. Thus
assume that \(X\) is a complete nonsingular curve. It is enough to show
triviality over a nonempty open subset of \(Z\), since the result then extends
by continuity.

Let \(\Omega^1\) be the sheaf of regular 1-forms on \(X\), and put
\(g=\dim H^0(X,\Omega^1)\). Choose \(P_1,\ldots,P_g\) such that, for
\(D=\sum P_i\),
\[
\dim H^0(X,\Omega^1\otimes\mathcal O_X(-D))=0.
\]
Let \(p_1:X\times Y\times Z\to X\) and
\(L'=L\otimes p_1^*L_X(D)\). Since
\[
\dim H^1(X,L'_{(y,z_0)})
=\dim H^0(X,\Omega^1\otimes\mathcal O_X(-D))=0,
\]
semicontinuity and completeness of \(Y\) allow us, after shrinking \(Z\) around
\(z_0\), to assume \(H^1(X,L'_{(y,z)})=0\) for all \((y,z)\). Hence
\[
\dim H^0(X,L'_{(y,z)})=\chi(L'_{(y,z)})
=\chi(\mathcal O_X(D))=1.
\]
Base change gives that \(p_{23*}L'\) is invertible and that its fiber maps to
\(H^0(X,L'_{(y,z)})\) are isomorphisms. On an open set \(U\subset Y\times Z\)
where it is trivial, let \(\sigma_U\) be a generating section and let
\(\widetilde D_U\) be its zero divisor. These glue to an effective divisor
\(\widetilde D\) on \(X\times Y\times Z\).

Every fiber over \(X\times\{y\}\times\{z_0\}\) and
\(X\times\{y_0\}\times\{z\}\) is \(D\). If \(P\ne P_i\), the support of
\(\widetilde D\) over \(\{P\}\times Y\times Z\) projects to a proper closed
subset of \(Z\); purity forces it to be a union of
\(\{P\}\times Y\times T_i\), which is impossible because it misses
\(\{P\}\times\{y_0\}\times Z\). Thus
\[
\widetilde D=\sum_i n_i\{P_i\}\times Y\times Z.
\]
Restricting to \(X\times\{y_0\}\times\{z_0\}\) gives \(n_i=1\). Therefore
\(L'_{(y,z)}\simeq L_X(D)\), and \(L|_{X\times\{y\}\times\{z\}}\) is trivial.
\end{proof}




\section{Applications of the theorem of the square}
\label{mumford-source-II6-applications}
\dcref{M:ch2:II.6}
\uses{mumford-thm-seesaw,mumford-thm-cube-varieties}

For a line bundle $L$ on an abelian variety $X$, put
$\phi_L(x)=[T_x^*L\otimes L^{-1}]$ and
$K(L)=\ker\phi_L=\{x:T_x^*L\simeq L\}$.
\source{mumford-abelian-varieties:page-0071}

\begin{proposition}[Closedness of the translation kernel]
\label{mumford-prop-KL-closed}
\dcref{M:ch2:II.6}
\uses{mumford-thm-seesaw}
$K(L)$ is a Zariski-closed subgroup of $X$.
\source{mumford-abelian-varieties:page-0071}
\end{proposition}
\begin{proof}
Apply the seesaw theorem to $m^*L\otimes p_2^*L^{-1}$ on $X\times X$.
The locus of $x$ for which its restriction to $\{x\}\times X$ is trivial is
closed, and that restriction is $T_x^*L\otimes L^{-1}$.  It is therefore
exactly $K(L)$.
\end{proof}

\begin{proposition}[Effective-divisor criterion]
\label{mumford-prop-effective-divisor-criterion}
\dcref{M:ch2:II.6}
\uses{mumford-prop-KL-closed,mumford-thm-seesaw}
Let $D$ be an effective divisor on $X$, $L=\mathcal O_X(D)$, and
$H=\{x:T_x^*D=D\}$.  The following are equivalent:
\begin{enumerate}
\item $H$ is finite;
\item $K(L)$ is finite;
\item $|2D|$ is base-point free and defines a finite morphism
      $X\to\mathbf P^N$;
\item $L$ is ample.
\end{enumerate}
\source{mumford-abelian-varieties:page-0071}\source{mumford-abelian-varieties:page-0072}\source{mumford-abelian-varieties:page-0073}
\end{proposition}
\begin{proof}
The implications (iii)$\Rightarrow$(iv) and (ii)$\Rightarrow$(i) are the
standard finite-morphism criterion and $K(L)\supset H$.  If $K(L)$ is not
finite, let $Y=K(L)^0$.  The restriction $L_Y$ is ample and invariant under
all translations by $Y$.  The seesaw theorem makes
$m^*L_Y\otimes p_1^*L_Y^{-1}\otimes p_2^*L_Y^{-1}$ trivial; pullback by
$y\mapsto(y,-y)$ makes $L_Y\otimes(-1_Y)^*L_Y$ trivial.  This is impossible
because it is ample on the positive-dimensional $Y$, proving (iv)$\Rightarrow$(ii).

Assume (i).  The divisors $T_x^*D+T_{-x}^*D$ lie in $|2D|$.  Given $v\in X$,
choose $x$ with $v\pm x\notin\operatorname{Supp}D$; hence $|2D|$ has no
base points and defines $\phi:X\to\mathbf P^N$.  If $\phi$ were not finite,
there would be an irreducible curve $C$ contracted by $\phi$, so every member
of $|2D|$ would contain $C$ or be disjoint from it.  For almost all $x$,
$C$ is disjoint from $T_x^*D+T_{-x}^*D$.

We use the following lemma.  If $C$ is a curve and $E$ an irreducible divisor
with $C\cap E=\varnothing$, then $E$ is invariant under translation by
$x_1-x_2$ for all $x_1,x_2\in C$.  Indeed, $\mathcal O_X(E)|_C$ is trivial,
so every translate has degree zero on $C$.  Thus a translate of $C$ either
misses $E$ or is contained in $E$.  For $y\in E$, the translate
$T_{y-x_2}(C)$ meets $E$ at $y$ and is consequently contained in $E$;
therefore $y-x_2+x_1\in E$.

Writing $D=\sum D_i$, the lemma makes every $D_i$ invariant under all
$x_1-x_2$ with $x_i\in C$, contradicting (i).  Thus $\phi$ is finite and
(i)$\Rightarrow$(iii).
\end{proof}

\begin{theorem}[Projectivity of abelian varieties]
\label{mumford-thm-abelian-projective}
\dcref{M:ch2:II.6}
\uses{mumford-prop-effective-divisor-criterion}
Every abelian variety is projective.
\source{mumford-abelian-varieties:page-0073}
\end{theorem}
\begin{proof}
Choose an affine open $U\subset X$ and let $D_1,\ldots,D_r$ be the
irreducible components of $X-U$, with $D=\sum D_i$.  Translate so that
$0\in U$.  The subgroup $H=\{x:T_x^*D=D\}$ is closed, and each $x\in H$
preserves $U$, hence $H\subset U$.  Since $H$ is complete and $U$ is affine,
$H$ is finite.  The criterion therefore makes $\mathcal O_X(D)$ ample, so a
power embeds $X$ in projective space.
\end{proof}

\begin{proposition}[Hilbert-polynomial degree]
\label{mumford-prop-degree-hilbert}
\dcref{M:ch2:II.6}
Let $X$ be complete of dimension $g$, $L$ invertible, and $\mathcal F$ coherent.
Write $P_{\mathcal F}(n)=\chi(\mathcal F\otimes L^n)$ and
$d_L(\mathcal F)/g!$ for its leading coefficient.  Then
\[
d_L(\mathcal F)=\operatorname{rank}(\mathcal F)\deg L.
\]
If $f:Y\to X$ is a surjective morphism of complete $g$-folds, then
\[
\deg f^*L=(\deg f)\deg L.
\]
\source{mumford-abelian-varieties:page-0075}\source{mumford-abelian-varieties:page-0076}
\end{proposition}
\begin{proof}
Choose a nonzero ideal sheaf $\mathcal J$ with an exact sequence
$0\to\mathcal J^{\operatorname{rank}\mathcal F}\to\mathcal F\to\mathcal G\to0$
where $\mathcal G$ is torsion.  Its support has dimension $<g$, so it does
not affect the leading coefficient.  Additivity of $\chi$ and
$0\to\mathcal J\to\mathcal O_X\to\mathcal O_X/\mathcal J\to0$ give
$d_L(\mathcal F)=\operatorname{rank}(\mathcal F)d_L(\mathcal J)
=\operatorname{rank}(\mathcal F)\deg L$.

For (2), projection formula gives
$R^pf_*(f^*L^n)=R^pf_*\mathcal O_Y\otimes L^n$.  The Leray spectral sequence
therefore yields
\[
\chi(f^*L^n)=\sum_p(-1)^p\chi(R^pf_*\mathcal O_Y\otimes L^n).
\]
For $p>0$ the higher direct images are supported on a proper closed subset,
while $f_*\mathcal O_Y$ has rank $\deg f$.  Comparing the coefficients of
$n^g$ proves the formula.
\end{proof}

\begin{corollary}[Degree of multiplication]
\label{mumford-cor-degree-multiplication-appendix}
\dcref{M:ch2:II.6}
\uses{mumford-prop-degree-hilbert,mumford-thm-cube-varieties}
For an abelian variety of dimension $g$, $\deg(n_X)=n^{2g}$.
\source{mumford-abelian-varieties:page-0076}
\end{corollary}
\begin{proof}
Choose an ample symmetric line bundle $L$.  The theorem of the square gives
$n_X^*L\simeq L^{n^2}$, hence
$\deg n_X\deg L=\deg(n_X^*L)=\deg(L^{n^2})=n^{2g}\deg L$.
Since $\deg L>0$, cancel to obtain the assertion.
\end{proof}

\section{Dividing varieties by finite groups}
\label{mumford-source-II7}
\dcref{M:ch2:II.7}
\uses{mumford-def-abelian-variety}

\begin{theorem}[Finite group quotient]
\label{mumford-thm-finite-group-quotient}
\dcref{M:ch2:II.7}
\uses{mumford-def-abelian-variety}
Let a finite group $G$ act on a variety $X$, with every orbit contained in an
affine open. Then there is a quotient variety $Y=X/G$ with
$\mathcal O_Y=\pi_*\mathcal O_X^G$; $\pi$ is finite, surjective, separable,
and etale when the action is free. If $X$ is affine, so is $Y$.
\source{mumford-abelian-varieties:page-0077}\source{mumford-abelian-varieties:page-0078}\source{mumford-abelian-varieties:page-0079}
\end{theorem}
\begin{proof}
If $U'$ is affine and contains an orbit $Gx$, then
$U=\bigcap_{g\in G}gU'$ is affine, $G$-stable, and contains $x$.  Thus it
suffices to prove the assertion for $X=\operatorname{Spec}A$.  Write
$A=k[x_1,\ldots,x_n]$, $v=|G|$, and let $B=A^G$.  If $\sigma_j(x_i)$ is
the $j$th elementary symmetric function in the orbit of $x_i$, put
$B'=k[\sigma_j(x_i)]$.  Each $x_i$ satisfies
\[
 T^v-\sigma_1(x_i)T^{v-1}+\cdots+(-1)^v\sigma_v(x_i)=0,
\]
so $A$ is finite over the noetherian ring $B'$.  Since
$B'\subset B\subset A$, $B$ is finite over $B'$ and $A$ is finite over $B$.
The inclusion $B\hookrightarrow A$ therefore defines a finite surjective map
$\pi:\operatorname{Spec}A\to\operatorname{Spec}B$.

If $R=K(A)$, then $R^G=K(B)$: for $a/b\in R^G$,
\[
 \frac ab=a\left(\prod_{g\ne e}g(b)\right)\left(\prod_{g\in G}g(b)\right)^{-1},
\]
and the numerator and denominator on the right are invariant.  Thus the
extension of quotient fields is separable.  The invariant direct image is the
intersection of the kernels of $f\mapsto g(f)-f$, and the affine calculation
identifies it with $\mathcal O_Y$.

If two points have distinct $G$-orbits, choose $f\in A$ equal to $1$ on one
orbit and $0$ on the other.  The product $\prod_{g\in G}g(f)$ is invariant and
separates their images, so the finite map has the orbit quotient topology.

Finally, complete at $y=\pi(x)$.  The Chinese remainder theorem gives
\[
 \widehat A\simeq\prod_{g\in G}\widehat{\mathcal O}_{X,gx}.
\]
The exact sequence
\[
0\to B\to A\to\prod_{g\in G}A,
\qquad a\mapsto(g(a)-a)_g,
\]
remains exact after the flat completion $\widehat B$.  Identifying all
completed local factors by the action, $G$ permutes the factors, and its
invariants are the diagonal copy of $\widehat{\mathcal O}_{X,x}$.  Hence
$\widehat{\mathcal O}_{Y,y}\to\widehat{\mathcal O}_{X,x}$ is an isomorphism
when the action is free, proving that $\pi$ is etale.  The affine quotients
glue over the $G$-stable affine cover.
\end{proof}

\begin{proposition}[Descent of coherent sheaves]
\label{mumford-prop-coherent-descent-finite-quotient}
\dcref{M:ch2:II.7}
\uses{mumford-thm-finite-group-quotient}
If $G$ acts freely on $X$ and $Y=X/G$, pullback is an equivalence between
coherent sheaves on $Y$ and coherent $G$-sheaves on $X$.  Its inverse is
$\mathcal G\mapsto\pi_*\mathcal G^G$, and locally free sheaves correspond with
the same rank.
\source{mumford-abelian-varieties:page-0080}\source{mumford-abelian-varieties:page-0081}\source{mumford-abelian-varieties:page-0082}
\end{proposition}
\begin{proof}
There are natural maps
\[
 S(\mathcal F):\mathcal F\to\pi_*(\pi^*\mathcal F)^G,qquad
 T(\mathcal G):\pi^*(\pi_*\mathcal G^G)\to\mathcal G.
\]
Affinely, with $X=\operatorname{Spec}A$, $Y=\operatorname{Spec}B$,
$B=A^G$, these become
\[
 S(M):M\to(M\otimes_BA)^G,qquad
 T(N):(N^G)\otimes_BA\to N.
\]
The composite after tensoring $S(M)$ with $A$ is the identity.  Since $A$ is
faithfully flat over $B$, it is enough to prove that all $T(N)$ are isomorphisms.
After completion at a point of $Y$, freeness identifies
$A\otimes_B\widehat B$ with a product of copies of $\widehat B$, one for each
element of $G$, with $G$ acting by simply transitive permutation.  In this
model the map $T(N)$ is immediate; faithful flatness of completion descends
the isomorphism.  The same argument preserves finite projective modules and
therefore local freeness and rank.
\end{proof}

\begin{proposition}[Translation quotients]
\label{mumford-prop-translation-quotient-isogeny}
\dcref{M:ch2:II.7}
\uses{mumford-thm-finite-group-quotient}
For a finite subgroup $K$ of an abelian variety $X$, the quotient $X/K$ is an
abelian variety and $X\to X/K$ is an etale isogeny. Conversely, every isogeny
is a quotient by its finite kernel.
\source{mumford-abelian-varieties:page-0083}\source{mumford-abelian-varieties:page-0084}\source{mumford-abelian-varieties:page-0085}
\end{proposition}
\begin{proof}
Translations by $K$ give a free finite-group action, so the quotient theorem
gives a finite etale map $X\to X/K$. The group law on the abstract quotient
is a morphism by applying the quotient property to the addition map; inversion
is treated similarly. Conversely, an isogeny is the quotient by its finite
kernel.
\end{proof}

\begin{proposition}[Characters and descended line bundles]
\label{mumford-source-character-kernel-pic}
\dcref{M:ch2:II.7}
\uses{mumford-thm-finite-group-quotient}
If $G$ acts freely on $X$ and $Y=X/G$, then for characters $\alpha:G\to k^*$,
\[
 \widehat G\simeq\ker[\Pic Y\to\Pic X],
\]
and if $|G|$ is prime to the characteristic, every coherent sheaf on $Y$ is
a direct summand of $\pi_*(\pi^*\mathcal F)$.
\source{mumford-abelian-varieties:page-0082}\source{mumford-abelian-varieties:page-0083}
\end{proposition}
\begin{proof}
An action on the trivial sheaf covering the action on $X$ sends the unit
section to a nowhere-vanishing regular function, hence to a scalar because
$X$ is complete. This scalar is a character; conversely every character
defines the action $g(f)=\alpha(g)^{-1}(f\circ g^{-1})$.
\end{proof}

\begin{corollary}[Divisibility and finite torsion]
\label{mumford-cor-divisible-finite-torsion}
\dcref{M:ch2:II.7}
An abelian variety $X$ is divisible and $X_n$ is finite for every $n>1$.
\source{mumford-abelian-varieties:page-0073}
\end{corollary}
\begin{proof}
For an ample line bundle $L$, the theorem of the square gives
\[
 n_X^*L\simeq L^{\otimes n(n+1)/2}\otimes(-1_X)^*L^{\otimes n(n-1)/2},
\]
which is ample. Since its restriction to $\ker(n_X)$ is trivial, the kernel
cannot contain a positive-dimensional subvariety. Thus it is finite, and the
surjectivity follows from the dimension theorem.
\end{proof}

\begin{proposition}[Degree and separability of multiplication]
\label{mumford-prop-multiplication-degree-separability}
\dcref{M:ch2:II.7}
For $g=\dim X$,
\[
 \deg(n_X)=n^{2g},\qquad n_X\text{ is separable}\Longleftrightarrow p\nmid n.
\]
If $p\nmid n$, then $X_n\simeq(\mathbf Z/n\mathbf Z)^{2g}$; for some
$0\le i\le g$, $X_{p^m}\simeq(\mathbf Z/p^m\mathbf Z)^i$.
\source{mumford-abelian-varieties:page-0073}\source{mumford-abelian-varieties:page-0074}\source{mumford-abelian-varieties:page-0075}
\end{proposition}
\begin{proof}
For equal-dimensional complete varieties,
$(f^*D_1\cdots f^*D_g)=\deg(f)(D_1\cdots D_g)$. For an ample symmetric
divisor $D$, $n_X^*D\sim n^2D$, hence $\deg(n_X)=n^{2g}$. If $p\nmid n$,
this degree is prime to $p$, so $n_X$ is separable and $\#X_n=n^{2g}$;
counting all $X_m$ for $m\mid n$ gives the stated group. If $p\mid n$,
$d(n_X)=0$, the rational differential map is zero, and the inseparable degree
is at least $p^g$. Thus $X_p\simeq(\mathbf Z/p\mathbf Z)^i$, and divisibility
gives the assertion for $p^m$.
\end{proof}

\section{The dual abelian variety in characteristic zero}
\label{mumford-source-II8}
\dcref{M:ch2:II.8}
\uses{mumford-thm-cube-varieties,mumford-thm-seesaw}

\begin{definition}[The dual variety]
\label{mumford-def-piczero}
\dcref{M:ch2:II.8}
\uses{mumford-thm-cube-varieties}
$\Pic^0(X)$ is the subgroup of line bundles $L$ for which
$\phi_L(x)=T_x^*L\otimes L^{-1}$ is identically zero. In characteristic zero
it has a natural structure of an abelian variety, denoted $\widehat X$.
\source{mumford-abelian-varieties:page-0085}\source{mumford-abelian-varieties:page-0086}


\notready
\end{definition}

\begin{theorem}[Dual abelian variety, characteristic zero]
\label{mumford-thm-dual-char-zero}
\dcref{M:ch2:II.8}
\uses{mumford-thm-cube-varieties,mumford-thm-seesaw,mumford-thm-finite-group-quotient}
For every abelian variety $X$ over a characteristic-zero field there is an
abelian variety $\widehat X$ representing $\Pic^0(X)$, with a Poincare bundle
$P_X$ on $X\times\widehat X$ trivial on both coordinate axes. Every line
bundle in $\Pic^0(X)$ is represented uniquely by a point of $\widehat X$.
\source{mumford-abelian-varieties:page-0086}\source{mumford-abelian-varieties:page-0087}\source{mumford-abelian-varieties:page-0088}\source{mumford-abelian-varieties:page-0089}\source{mumford-abelian-varieties:page-0090}\source{mumford-abelian-varieties:page-0091}
\end{theorem}
\begin{proof}
The theorem of the square gives, for $L\in\Pic^0(X)$,
\[
 T_x^*L\simeq L,\qquad (x+y)^*L\simeq T_x^*L\otimes T_y^*L\otimes L^{-1},
 \qquad n_X^*L\simeq L^n.
\]
Conversely, for arbitrary $L$ one has
\[
 n_X^*L\simeq L^{n^2}\otimes
 [L\otimes(-1_X)^*L^{-1}]^{(n-n^2)/2},
\]
and the bracketed factor lies in $\Pic^0(X)$ by the theorem of the square.
Any finite-order line bundle is therefore in $\Pic^0(X)$, since
$0=\phi_{L^n}(x)=\phi_L(nx)$ and $X$ is divisible.

If $L\in\Pic^0(X)$ is nontrivial, then $H^0(X,L)=0$: a nonzero section would
write $L=\mathcal O_X(D)$ with $D\ge0$, while
$L^{-1}\simeq(-1_X)^*L=\mathcal O_X((-1_X)^*D)$, forcing $D=0$.  If $k$ is
the least index with $H^k(X,L)\ne0$, pull back the isomorphism
$m^*L\simeq p_1^*L\otimes p_2^*L$ along $s_1(x)=(x,0)$.  The Kunneth
decomposition gives
\[
 H^k(X\times X,m^*L)\simeq
 \bigoplus_{i+j=k}H^i(X,L)\otimes H^j(X,L)=0,
\]
since in every summand one index is $<k$.  As $m\circ s_1=1_X$, the identity
on $H^k(X,L)$ factors through zero, a contradiction.  Thus all cohomology
of a nontrivial $L\in\Pic^0(X)$ vanishes.

Let $L$ be ample and put
\[
 K=m^*L\otimes p_1^*L^{-1}\otimes p_2^*(L^{-1}\otimes M^{-1})
\]
for $M\in\Pic^0(X)$.  The two Leray spectral sequences for the projections
$p_1,p_2:X\times X\to X$ have abutment $H^*(X\times X,K)$.  If
$M\simeq T_x^*L\otimes L^{-1}$, the restriction of $K$ to the $p_1$-fiber
over $x$ is a nontrivial member of $\Pic^0(X)$ and hence has no cohomology.
Therefore the first spectral sequence gives $H^*(X\times X,K)=0$.  For the
second, the support of every $R^kp_{2,*}K$ is contained in the finite set
$K(L)=\{x:T_x^*L\simeq L\}$.  The second spectral sequence then degenerates,
so all restrictions $K|_{X\times\{x\}}$ have zero cohomology.  At $x=0$ this
restriction is trivial and has nonzero $H^0$, a contradiction unless the
chosen $M$ is of the displayed form.  Hence $\phi_L:X\to\Pic^0(X)$ is
surjective.

Take $\widehat X=X/K(L)$, which exists by the finite-quotient theorem, and
let $\pi:X\to\widehat X$.  Put
\[
 K_0=m^*L\otimes p_1^*L^{-1}\otimes p_2^*L^{-1}.
\]
For $a\in K(L)$, translation by $(0,a)$ preserves $K_0$ because
$T_a^*L\simeq L$.  Normalize the resulting lift on
$\{0\}\times X\simeq L^{-1}(0)\times X$ to be
$(\lambda,x)\mapsto(\lambda,x+a)$.  The normalization is unique, and hence
the lifts form an action of $K(L)$.  Descent along $1_X\times\pi$ produces a
line bundle $P$ on $X\times\widehat X$ with
\[
 (1_X\times\pi)^*P\simeq K_0.
\]
Its fiber at $\pi(x)$ is $T_x^*L\otimes L^{-1}$, and its restriction to
$\{0\}\times\widehat X$ is trivial, so $P$ is normalized.

Finally, if $S$ is normal and $N$ is a line bundle on $X\times S$ whose
fibers lie in $\Pic^0(X)$ and whose restriction to $\{0\}\times S$ is trivial,
form
\[
 E=p_{12}^*N\otimes p_{13}^*P^{-1}
 \quad\text{on }X\times S\times\widehat X.
\]
The seesaw theorem makes the locus where
$E|_{X\times\{s,\alpha\}}$ is trivial a closed subset $\Gamma$ of
$S\times\widehat X$.  It is the graph of the set-theoretic classifying map
$f:S\to\widehat X$.  The projection $\Gamma\to S$ is bijective and, in
characteristic zero with $S$ normal, Zariski's Main Theorem makes it an
isomorphism.  Thus $f$ is a morphism and seesaw gives
$N\simeq(1_X\times f)^*P$.  This universal property identifies
$\widehat X$ with the representing abelian variety for $\Pic^0(X)$.
\end{proof}

\begin{proposition}[Biduality]
\label{mumford-prop-biduality-char-zero}
\dcref{M:ch2:II.8}
\uses{mumford-thm-dual-char-zero,mumford-source-character-kernel-pic}
There is a canonical isomorphism $X\simeq\widehat{\widehat X}$.
If $f:X\to Y$ is an isogeny, then $\widehat f:\widehat Y\to\widehat X$ is an
isogeny and $\ker f$ and $\ker\widehat f$ are canonically dual finite groups.
\source{mumford-abelian-varieties:page-0091}\source{mumford-abelian-varieties:page-0092}
\end{proposition}
\begin{proof}
The pullback map on Picard varieties sends $\Pic^0(Y)$ into $\Pic^0(X)$ and
defines $\widehat f$. If $f$ is an isogeny, the kernel of $\widehat f$ is the
kernel of pullback on Picard groups, which is dual to $\ker f$ by the finite
quotient character calculation. Equal dimensions then imply that $\widehat f$
is an isogeny. Applying this construction twice gives the canonical bidual
identification.
\end{proof}

\begin{definition}[Divisorial correspondence]
\label{mumford-source-divisorial-correspondence}
\dcref{M:ch2:II.8}
A divisorial correspondence between $X,Y$ is a line bundle on $X\times Y$
trivial on $\{0\}\times Y$ and $X\times\{0\}$.
\source{mumford-abelian-varieties:page-0092}
\end{definition}

\begin{proposition}[Characterization of the Poincare correspondence]
\label{mumford-source-divisorial-biduality}
\dcref{M:ch2:II.8}
For equal-dimensional $X,Y$ and a divisorial correspondence $Q$, the
conditions that $Q|_{\{x\}\times Y}$ be trivial only for $x=0$ and that
$Q|_{X\times\{y\}}$ be trivial only for $y=0$ are equivalent. When they hold,
$X\simeq\widehat Y$, $Y\simeq\widehat X$, and $Q$ is the Poincare bundle.
\source{mumford-abelian-varieties:page-0092}\source{mumford-abelian-varieties:page-0093}
\end{proposition}
\begin{proof}
By the universal property, (1) gives an injective $X\to\widehat Y$ and hence
an isomorphism in equal dimensions and characteristic zero. The induced map
$\psi:Y\to\widehat X$ must be injective: otherwise factor it through
$Y/K$ for a nonzero finite subgroup $K$. The correspondence then induces
$X\to\widehat{Y/K}$ whose composite with $\widehat{Y/K}\to\widehat Y$ is
an isomorphism, contradicting the nontrivial kernel of the latter dual
isogeny. Symmetry gives (2) from (1).
\end{proof}

\section{Analytic comparison over $\mathbf C$}
\label{mumford-source-II9}
\dcref{M:ch2:II.9}
\uses{mumford-thm-appell-humbert,mumford-def-piczero}

\begin{theorem}[Analytic translation formula]
\label{mumford-thm-analytic-dual-comparison}
\dcref{M:ch2:II.9}
\uses{mumford-thm-appell-humbert,mumford-def-piczero}
For $L(H,\alpha)$ on $X=V/U$,
\[
 T_{\pi(a)}^*L(H,\alpha)\simeq L(H,\alpha\gamma_a),
 \qquad \gamma_a(u)=e^{2\pi iE(a,u)}.
\]
Consequently
\[
 K(L)=U^\perp/U,
\quad U^\perp=\{a:E(a,u)\in\mathbf Z\ \forall u\in U\},
\]
and $L\in\Pic^0(X)$ iff $H=0$; $K(L)$ is finite iff $H$ is nondegenerate.
\source{mumford-abelian-varieties:page-0094}\source{mumford-abelian-varieties:page-0095}
\end{theorem}
\begin{proof}
Pull back the factor of automorphy under translation by $a$ and conjugate by
$e^{-\pi\overline{H(z,a)}}$. The multiplier changes by
$e^{\pi(H(a,u)-H(u,a))}=e^{2\pi iE(a,u)}$.
\end{proof}

\begin{proposition}[Analytic construction of the dual]
\label{mumford-source-analytic-dual}
\dcref{M:ch2:II.9}
For $X=V/U$, let
\[
 U'=\{l\in\overline T:\operatorname{Im}l(u)\in\mathbf Z\ \forall u\in U\}.
\]
Then $\widehat X=\overline T/U'$, and the Poincare bundle is
$L(H,\alpha)$ with
\[
 H((x_1,l_1),(x_2,l_2))=\overline{l_2(x_1)}+l_1(x_2),
 \qquad \alpha((u,l))=e^{-\pi i\operatorname{Im}l(u)}.
\]
The point represented by $l$ corresponds to $L(0,\alpha_l)$ with
$\alpha_l(u)=e^{2\pi i\operatorname{Im}l(u)}$.
\source{mumford-abelian-varieties:page-0095}\source{mumford-abelian-varieties:page-0096}\source{mumford-abelian-varieties:page-0097}

\notready
\end{proposition}

\begin{remark}[Normalization of the analytic dual identification]
\label{mumford-source-analytic-dual-normalization}
\dcref{M:ch2:II.9}
The two analytic descriptions of the map from $\overline T$ to
$\operatorname{Pic}^0(X)$ differ by the scalar normalization $2i$; explicitly,
the factor-of-automorphy description sends
\[
 l\longmapsto L(0,\alpha_l^*),
 \qquad \alpha_l^*(u)=e^{4\pi i\operatorname{Re}l(u)}.
\]
\source{mumford-abelian-varieties:page-0098}
\end{remark}

\label{chap:mumford-schemes}





\section{The scheme-theoretic theorem of the cube}
\label{mumford-III10-source}
\dcref{M:ch3:III.10}

\begin{proposition}[Fibres of a morphism from an abelian variety]
\label{mumford-prop-abelian-fibre-kernel}
\dcref{M:ch3:III.10}
Let $f:X\to Y$ be a morphism of varieties with $X$ an abelian variety. If
$F_x$ is the connected component of the fibre $f^{-1}(f(x))$ containing $x$,
then there is a closed connected subgroup $F\subset X$ such that
$F_x=x+F$ for every $x$.
\source{mumford-abelian-varieties:page-0099}
\end{proposition}
\begin{proof}
For fixed $x$, apply the rigidity lemma to
$\phi:X\times F_x\to Y$, $\phi(z,w)=f(z+w)$, since $F_x$ is complete and
connected and $\phi(\{e\}\times F_x)$ is constant. Hence
$f(z-x+F_x)=f(z)$, so connectedness gives
$F_z\supset z-x+F_x$. Interchanging $x,z$ gives equality. Taking
$F=F_e$ yields $F_z=z+F$. If $u\in F$, then
$F_{-u}=-u+F$ contains $e$, hence equals $F_e=F$. Thus $-u+F=F$ for all
$u\in F$, proving that $F$ is a subgroup; it is closed and connected by
construction.
\end{proof}

\begin{theorem}[Effective divisors and their stabilizers]
\label{mumford-thm-effective-divisor-stabilizer}
\dcref{M:ch3:III.10}
\uses{mumford-prop-abelian-fibre-kernel}
For an effective divisor $D$ on an abelian variety $X$, let
$H(D)=\{x\mid T_x^*D=D\}$ (equality of divisors), let $L=L(D)$, and let
$f:X\to\mathbf P(H^0(X,L^2))$ be the morphism defined by the base-point-free
bundle $L^2$. If $F(D)=\ker f$, then
\[
H(D)\text{ is Zariski closed},\qquad H(D)^0=K(L)^0=F(D).
\]
\source{mumford-abelian-varieties:page-0099}
\emph{The source states this theorem without proof.}
\end{theorem}

\begin{proposition}[Maximal triviality subscheme]
\label{mumford-prop-maximal-triviality-scheme}
\dcref{M:ch3:III.10}
\uses{mumford-thm-seesaw}
Let $X$ be a complete variety, $Y$ any scheme and $L$ a line bundle on
$X\times Y$. There exists a unique closed subscheme $Y_1\hookrightarrow Y$
such that:
\begin{enumerate}
\item if $L_1$ is the restriction of $L$ to $X\times Y_1$, then
there is a line bundle $M_1$ on $Y_1$ and an isomorphism
$p_2^*M_1\simeq L_1$;
\item if $f:Z\to Y$ and $p_2^*K\simeq(1_X\times f)^*L$ for a line bundle
$K$ on $Z$, then $f$ factors through $Y_1$.
\end{enumerate}
\source{mumford-abelian-varieties:page-0100}
\source{mumford-abelian-varieties:page-0101}
\source{mumford-abelian-varieties:page-0102}
\end{proposition}
\begin{proof}
Uniqueness follows because the two closed immersions factor through one
another. If $p_2^*M_1\simeq L_1$, the Kunneth formula gives
$M_1\simeq p_{2,*}L_1$; thus it is enough to require that this direct image
be invertible and that the natural map $p_2^*p_{2,*}L_1\to L_1$ be an
isomorphism. The assertion is local on $Y$: local subschemes agree on
overlaps by uniqueness.

Take $Y=\operatorname{Spec}A$ and, after shrinking, a free complex
$0\to A^0\xrightarrow{\phi}A^1\to\cdots$ computing direct images of $L$
universally. If $M=\operatorname{coker}(A^1\xrightarrow{\phi}A^0)$, then for
every $A$-algebra $B$,
\[
0\to\operatorname{Hom}_B(M\otimes_A B,B)\to B^0\xrightarrow{\phi_B}B^1
\]
is exact. Hence
$p_{2,*}(1_X\times f)^*L\simeq\operatorname{Hom}_A(M,B)$.
Let $F$ be the closed set of points where $L_y$ is trivial. Outside $F$ the
empty subscheme works. At $y\in F$,
\[
1=\dim H^0(X,L_y)=\dim_k M/\mathfrak m_yM,
\]
so Nakayama gives, after shrinking, $M\simeq A/\mathfrak a$. For the
subscheme defined by $\mathfrak a$, the direct image is
$\operatorname{Hom}_A(A/\mathfrak a,A/\mathfrak a)\simeq A/\mathfrak a$.
The evaluation map
\[
p_2^*p_{2,*}L_1\xrightarrow{\lambda}L_1
\]
is an isomorphism on the fibre over $y$: its fibre map is surjective because
\(\operatorname{Hom}_A(A/\mathfrak a,A/\mathfrak a)\to
\operatorname{Hom}_A(A/\mathfrak a,A/\mathfrak m_y)\) is surjective and
$L_y$ is trivial. The non-isomorphism locus is closed, and its projection is
closed and avoids $y$; shrinking once more gives (a).

For (b), take $Z=\operatorname{Spec}B$ affine and trivialize $K$. Then
$p_{2,*}(1_X\times f)^*L\simeq B$, while the universal complex gives
$B\simeq\operatorname{Hom}_A(A/\mathfrak a,B)$. Therefore
$\mathfrak aB=0$, so $A\to B$ factors through $A/\mathfrak a$.
\end{proof}

\begin{theorem}[Theorem of the cube, scheme-theoretic form]
\label{mumford-thm-cube-schemes}
\dcref{M:ch3:III.10}
\uses{mumford-prop-maximal-triviality-scheme}
Let $X,Y$ be complete varieties, $Z$ a connected scheme, and $L$ a line
bundle on $X\times Y\times Z$. If the restrictions to
\(\{x_0\}\times Y\times Z$, $X\times\{y_0\}\times Z$ and
$X\times Y\times\{z_0\}$ are trivial, then $L$ is trivial.
\source{mumford-abelian-varieties:page-0102}
\source{mumford-abelian-varieties:page-0103}
\source{mumford-abelian-varieties:page-0104}
\end{theorem}
\begin{proof}
Let $Z'$ be the maximal closed subscheme over which $L$ is trivial. It is
nonempty, since it contains $z_0$. It suffices, by connectedness, to show
that every point of $Z'$ has an open neighbourhood in $Z'$ equal to an open
neighbourhood in $Z$. At $z_0$, write $\mathfrak m$ for the maximal ideal
of $\mathcal O_{Z,z_0}$ and $I$ for the ideal of $Z'$. If $I\ne0$, Krull's
theorem gives $n>0$ with $\mathfrak m^n\supset I$ but
$\mathfrak m^{n+1}\not\supset I$. Put $\mathfrak a_1=\mathfrak m^{n+1}+I$;
choose $\mathfrak a_2$ with
$\mathfrak a_1\supset\mathfrak a_2\supset\mathfrak m^{n+1}$ and
$\dim_k\mathfrak a_1/\mathfrak a_2=1$. Thus
$\mathfrak a_1=\mathfrak a_2+k a$, with $\mathfrak a_1\supset I$ but
$\mathfrak a_2\not\supset I$.

Let $Z_i$ be the one-point subscheme defined by $\mathfrak a_i$ (and let
$Z_0=\{z_0\}$). The exact sequence
\[
0\to\mathcal O_{Z_0}\xrightarrow{a}\mathcal O_{Z_2}
\to\mathcal O_{Z_1}\to0
\]
induces
\[
0\to L_0\xrightarrow{a}L_2\to L_1\to0.
\]
Both $L_0$ and $L_1$ are trivial. If $s$ is the section of $L_1$ induced by
a trivialization, $L_2$ is trivial exactly when $s$ lifts to a section of
$L_2$: a lift gives a map from the structure sheaf which is an isomorphism
on the closed fibre, while a trivialization makes restriction on global
sections surjective.

Fix a trivialization of $L_0$. The obstruction to lifting $s$ is
$\xi\in H^1(X\times Y,\mathcal O_{X\times Y})$. The two assumed trivial
restrictions show that the images of $\xi$ under
\[
H^1(X\times Y,\mathcal O)\to H^1(X,\mathcal O_X),\qquad
H^1(X\times Y,\mathcal O)\to H^1(Y,\mathcal O_Y)
\]
are zero. The Kunneth formula identifies these two maps with the two
projections from
$H^1(X,\mathcal O_X)\oplus H^1(Y,\mathcal O_Y)$, so $\xi=0$. Thus $L_2$
is trivial, contradicting $\mathfrak a_2\not\supset I$. Hence $I=0$.
\end{proof}

\section{Basic theory of group schemes}
\label{mumford-III11-source}
\dcref{M:ch3:III.11}

\begin{definition}[Group scheme and functor of points]
\label{mumford-def-group-scheme}
\dcref{M:ch3:III.11}
A group scheme is a scheme $G$ with morphisms $m:G\times G\to G$,
$e:\operatorname{Spec}k\to G$, and $i:G\to G$ satisfying associativity,
identity, and inverse diagrams. Equivalently, $G(S)=\operatorname{Hom}_k(S,G)$
is a group, functorially in $S$. The functor $X\mapsto\underline X$ is fully
faithful (Yoneda).
\source{mumford-abelian-varieties:page-0104}
\source{mumford-abelian-varieties:page-0105}
\source{mumford-abelian-varieties:page-0106}
\end{definition}

\begin{proposition}[Lie algebra of a group scheme]
\label{mumford-prop-group-scheme-lie}
\dcref{M:ch3:III.11}
\uses{mumford-def-group-scheme}
For a group scheme $G$, every tangent vector at $e$ extends uniquely to a
left-invariant vector field. The left-invariant vector fields form the Lie
algebra of $G$ under the Poisson bracket, and in characteristic $p$ under
the $p$-th power operation.
\source{mumford-abelian-varieties:page-0107}
\source{mumford-abelian-varieties:page-0108}
\source{mumford-abelian-varieties:page-0109}
\source{mumford-abelian-varieties:page-0110}
\end{proposition}
\begin{proof}
A vector field is a derivation $D:\mathcal O_X\to\mathcal O_X$, equivalently
$\mathcal O_X\to\Omega_X\to\mathcal O_X$. Tangent vectors at $x$ are
$\operatorname{Hom}_{\mathcal O_{X,x}}(\Omega_{X,x},k)$, and hence linear
forms on $\mathfrak m_x/\mathfrak m_x^2$. Put
$\Lambda=k[\epsilon]/(\epsilon^2)$. A derivation $D:A\to B$ is equivalent
to a homomorphism $A\to B\otimes_k\Lambda$, $a\mapsto a+(Da)\epsilon$.
Thus a vector field is an infinitesimal automorphism over $\Lambda$.

For a group scheme, left invariance says that this automorphism commutes with
right multiplication. If $\widetilde t:\operatorname{Spec}\Lambda\to G$ is
the value at the identity, the commutative diagram forces the automorphism to
be right multiplication by $\widetilde t$, and conversely. This proves the
canonical identification of left-invariant vector fields with $T_eG$.
The commutator $[D_1,D_2]=D_1D_2-D_2D_1$ and, in characteristic $p$, $D^p$
are again vector fields and preserve left invariance.
\end{proof}

\begin{remark}[Lie identities and commutative groups]
\label{mumford-rem-lie-identities}
\dcref{M:ch3:III.11}
\uses{mumford-prop-group-scheme-lie}
The bracket is bilinear, alternating, and satisfies Jacobi. In characteristic
$p$, $\operatorname{ad}(X^p)=(\operatorname{ad}X)^p$ and
\[
(X+Y)^p=X^p+Y^p+F_p(\operatorname{ad}X,\operatorname{ad}Y)Y.
\]
If $G$ is commutative, the bracket is zero: using
$k[\epsilon,\epsilon']/ (\epsilon^2,\epsilon'^2)$, the commutator of the
two infinitesimal translations is the translation by the commutator of two
$S$-valued points, which is the identity.
\source{mumford-abelian-varieties:page-0110}
\source{mumford-abelian-varieties:page-0111}
\source{mumford-abelian-varieties:page-0112}
\end{remark}

\begin{theorem}[Characteristic-zero smoothness]
\label{mumford-thm-abelian-smooth}
\dcref{M:ch3:III.11}
\uses{mumford-prop-group-scheme-lie}
Every group scheme over a field of characteristic zero is smooth and reduced.
\source{mumford-abelian-varieties:page-0112}
\source{mumford-abelian-varieties:page-0113}
\end{theorem}
\begin{proof}
More generally, let $x$ be a point of a characteristic-zero scheme $X$ and
suppose vector fields $D_1,\ldots,D_n$, with
$n=\dim_k\mathfrak m_x/\mathfrak m_x^2$, give independent tangent vectors.
Choose $x_i\in\mathfrak m_x$ with $(D_ix_j)(x)=\delta_{ij}$. Since
$D_i(\mathfrak m_x^r)\subset\mathfrak m_x^{r-1}$, the derivations extend to
$\widehat{\mathcal O}_x$. Define
\[
\alpha:k[[t_1,\ldots,t_n]]\to\widehat{\mathcal O}_x,\quad t_i\mapsto x_i,
\]
and
\[
\beta(f)=\sum_{\nu\ge0}\frac{D^\nu f}{\nu!}(x)t^\nu,
\quad D^\nu=D_1^{\nu_1}\cdots D_n^{\nu_n}.
\]
Leibniz and induction show that $\beta$ is a continuous homomorphism.
Both maps are surjective: $\alpha$ because the $x_i$ generate the maximal
ideal, and $\beta$ because $\beta(x_i)\equiv t_i$ modulo the square of the
maximal ideal. Hence $\beta\alpha$ is an automorphism, so $\alpha$ is an
isomorphism. The completed local ring is regular, proving smoothness.
\end{proof}

\begin{definition}[Subgroup schemes and kernels]
\label{mumford-lem-group-scheme-kernel}
\dcref{M:ch3:III.11}
\uses{mumford-def-group-scheme}
A closed subscheme $H\subset G$ is a subgroup scheme if multiplication on
$H\times H$ factors through $H$. The fibre over the identity of a homomorphism
of group schemes is its kernel and is a closed subgroup scheme.
In characteristic $p$, with $\mathfrak m$ the maximal ideal at $e$, the
subscheme $G_n=\operatorname{Spec}(\mathcal O_e/\mathfrak m^{(p^n)})$ is a
subgroup scheme and $\Lie(G_n)=\Lie(G)$ for $n\ge1$.
\source{mumford-abelian-varieties:page-0113}
\source{mumford-abelian-varieties:page-0114}
\end{definition}
\begin{proof}
For $f\in\mathfrak m$, write $m^*f=g+h$ in the local ring at $(e,e)$,
with $g$ in the sum of the two maximal ideals and $h$ a unit. In
characteristic $p$, $m^*(f^{p^n})$ lies in the ideal generated by the two
$p^n$-power ideals, so multiplication factors through $G_n$. The statement
about Lie algebras is immediate from the definition.
\end{proof}

\section{Left-invariant differential operators}
\label{mumford-III11-hyperalgebra}
\dcref{M:ch3:III.11}

\begin{definition}[Hyperalgebra]
\label{mumford-def-hyperalgebra}
\dcref{M:ch3:III.11}
\uses{mumford-def-group-scheme}
Put
\[
H_x=\operatorname{Hom}_{\mathrm{cont}}(\mathcal O_{x,G},k),\qquad
H=\bigoplus_{x\in G}H_x
 =\varinjlim_{Z\subset G\ {\text{finite}}}\Gamma(\mathcal O_Z)^*.
\]
The convolution is
\[
L_1*L_2(f)=L_1\otimes L_2(m^*f).
\]
The elements $\delta_x$ are convolution identities at points,
$\delta_e*L=L*\delta_e=L$, and evaluation at $1$ is the augmentation.
\source{mumford-abelian-varieties:page-0115}
\source{mumford-abelian-varieties:page-0116}
\end{definition}

\begin{proposition}[Invariant differential operators]
\label{mumford-prop-hyperalgebra-operators}
\dcref{M:ch3:III.11}
\uses{mumford-def-hyperalgebra}
Each $L\in H$ defines a left-invariant differential operator
\[
D_L(f)=(L\otimes1)m^*(f),\qquad D_Lf(e)=L(f),
\]
and $D_{L_1*L_2}=D_{L_1}\circ D_{L_2}$. If $G$ is commutative, $H$ is
commutative and the Lie bracket is zero.
\source{mumford-abelian-varieties:page-0116}
\source{mumford-abelian-varieties:page-0117}
\source{mumford-abelian-varieties:page-0118}
\end{proposition}
\begin{proof}
If $L$ is supported on a finite subscheme $Z$, the construction factors
through $G\times Z$ and is therefore a differential operator. Associativity
of $m$ gives the composition formula. Cocommutativity of $m^*$ for a
commutative group scheme gives commutativity of convolution.
\end{proof}

\section{Quotients by finite group schemes}
\label{mumford-III12-source}
\dcref{M:ch3:III.12}

\begin{definition}[Action and freeness]
\label{mumford-def-group-scheme-action}
\dcref{M:ch3:III.12}
\uses{mumford-def-group-scheme}
An action is a morphism $\mu:G\times X\to X$ satisfying the unit and
associativity diagrams. A morphism is invariant if $f\mu=fp_2$. The action
is free if $(\mu,p_2):G\times X\to X\times X$ is a closed immersion.
A $G$-linearization of a coherent sheaf $\mathcal F$ is an isomorphism
$p_2^*\mathcal F\simeq\mu^*\mathcal F$ satisfying the corresponding
associativity diagram and restricting to the identity at $e$.
\source{mumford-abelian-varieties:page-0119}
\source{mumford-abelian-varieties:page-0120}
\source{mumford-abelian-varieties:page-0121}
\source{mumford-abelian-varieties:page-0122}
\end{definition}

\begin{theorem}[Quotient by a finite group scheme]
\label{mumford-thm-finite-groupscheme-quotient}
\dcref{M:ch3:III.12}
\uses{mumford-def-group-scheme-action}
Let a finite group scheme $G$ act on $X$, with every orbit contained in an
affine open. There is a quotient $(Y,\pi)$ whose underlying topological
space is the orbit quotient and for which
$\mathcal O_Y\simeq\pi_*\mathcal O_X^G$. It is unique, finite and
surjective, and has the universal property for invariant morphisms.
If the action is free, $\pi$ is flat of degree $n=\dim_kR$ for
$G=\operatorname{Spec}R$, $G\times X\simeq X\times_YX$, and pullback is an
equivalence between coherent sheaves on $Y$ and coherent $G$-sheaves on $X$.
\source{mumford-abelian-varieties:page-0122}
\source{mumford-abelian-varieties:page-0123}
\end{theorem}
\begin{proof}
For (A), reduce to $X=\operatorname{Spec}A$. Let
$B=A^G=\{a\mid\mu^*(a)=1\otimes a\}$. The norm
$\operatorname{Nm}_A:R\otimes_kA\to A$ defines
$N(a)=\operatorname{Nm}_A(\mu^*(a))$. If
$\phi(a)=1\otimes a$ and
$\psi(\xi\otimes\eta\otimes a)=(m^*\xi\otimes1)(1\otimes\eta\otimes a)$,
functoriality and invariance of norm under the $R\otimes A$-algebra
automorphism $\psi$ give
\[
\mu^*N=\operatorname{Nm}_{R\otimes A}(1\otimes\phi)\mu^*
=\phi\operatorname{Nm}_A\mu^*=\phi N.
\]
Thus $N(A)\subset B$. For $a\in A$, the characteristic polynomial
$\chi_a(T)=N(T-a)=T^n+s_1T^{n-1}+\cdots+s_n$ has invariant coefficients.
Since $\mu^*(a)-a$ vanishes on the quotient by $\epsilon\otimes1$,
$\chi_a(a)=0$. Hence $A$ is integral over $B$, so $B$ is finitely generated
and $\pi:\operatorname{Spec}A\to\operatorname{Spec}B$ is finite and
surjective. The norm separates orbits. Finally the invariant sheaf is the
kernel of
\[
\pi_*\mathcal O_X\longrightarrow\pi_*\mathcal O_X\otimes_kR,
\qquad f\longmapsto\mu^*(f)-f\otimes1,
\]
which proves the sheaf assertion.

For (B), the canonical pullback isomorphism
$(g f)^*\mathcal F\simeq f^*g^*\mathcal F$ satisfies its associativity
diagram; since $\pi\mu=\pi p_2$, it gives the natural action on
$\pi^*\mathcal F$. For a $G$-sheaf with module $M$, define invariants
$M^G$ and the natural maps
\[
\mathcal F\to\pi_*(\pi^*\mathcal F)^G,qquad
A\otimes_BM^G\to M.
\]
It remains affine to prove these are isomorphisms.

Freeness makes
\[
\lambda:A\otimes_BA\to R\otimes_kA,\qquad
\lambda(a_1\otimes a_2)=\mu^*(a_1)(1\otimes a_2)
\]
surjective. Localize so that $B$ is local and $A$ semilocal. There are
$a_1,\ldots,a_n$ such that $\mu^*(a_i)$ is an $A$-basis of $R\otimes A$.
Then
\[
\mu^*(a)=\sum_i(1\otimes\lambda_i)\mu^*(a_i)
\Longleftrightarrow a=\sum_i\lambda_i a_i\text{ and }\lambda_i\in B.
\]
This identifies $A$ as a free, hence faithfully flat, $B$-module, proves
injectivity of $\lambda$, and gives $A\otimes_BM^G\simeq M$. If $M$ is
projective over $A$, faithful flatness shows $M^G$ is $B$-flat; finite
presentation makes it $B$-projective.
\end{proof}

\begin{proof}[Details of the affine descent step]
The implication in the displayed basis criterion from right to left follows
by applying $\mu^*$ and using $\mu^*(\lambda_i)=1\otimes\lambda_i$ for
$\lambda_i\in B$. Conversely, apply $1\otimes\mu^*$ and
$(1\otimes\mu^*)(\mu^*a)=(m^*\otimes1)(\mu^*a)$ to the expansion
$\mu^*(a)=\sum_i(1\otimes\lambda_i)\mu^*(a_i)$. Independence of the basis
$\mu^*(a_i)$ gives $\lambda_i\in B$, and $\epsilon\otimes1$ gives
$a=\sum_i\lambda_i a_i$. The same calculation gives
$A\otimes_BA\simeq R\otimes_kA$. For a $G$-sheaf with module $M$, write the
action as $\tau:A\otimes_BM\to M\otimes_BA$ and set
\[
N=\{m\in M\mid\tau(1\otimes m)=m\otimes1\}.
\]
Flatness identifies $N\otimes_BA$ with the kernel of
\[
M\otimes_BA\to M\otimes_BA\otimes_BA,\quad
m\otimes a\mapsto m\otimes1\otimes a-\tau(1\otimes m)\otimes a.
\]
 Associativity identifies this kernel with $\tau(1\otimes M)$, and faithful
 flatness gives $N\otimes_BA\simeq M$.
\source{mumford-abelian-varieties:page-0124}
\source{mumford-abelian-varieties:page-0125}
\source{mumford-abelian-varieties:page-0126}
\source{mumford-abelian-varieties:page-0127}
\source{mumford-abelian-varieties:page-0128}
\end{proof}

\begin{definition}[Epimorphism of group schemes]
\label{mumford-def-group-scheme-epimorphism}
\dcref{M:ch3:III.12}
A homomorphism $f:X\to Y$ is an epimorphism if it is surjective and
$f^*:\mathcal O_Y\to f_*\mathcal O_X$ is injective.
\source{mumford-abelian-varieties:page-0128}
\end{definition}

\begin{corollary}[Finite normal quotients]
\label{mumford-cor-finite-normal-quotient}
\dcref{M:ch3:III.12}
\uses{mumford-thm-finite-groupscheme-quotient}
If a finite normal subgroup scheme $G\subset X$ acts by right translations,
then $X/G$ is a group scheme, $\pi:X\to X/G$ is an epimorphism, and
$G=\ker(\pi)$. Conversely, an epimorphism with finite kernel is the quotient
by its kernel.
\source{mumford-abelian-varieties:page-0128}
\source{mumford-abelian-varieties:page-0129}
\source{mumford-abelian-varieties:page-0130}
\end{corollary}
\begin{proof}
Multiplication descends because $\pi\circ m$ is $G\times G$-invariant.
The identity $G\times X\simeq X\times_{X/G}X$ gives
$x\in\ker\pi\Longleftrightarrow\pi(x)=\pi(e)\Longleftrightarrow x\in G(S)$.
Conversely factor through $X/G\to Y$. It is finite; translated affine opens
and Nakayama reduce isomorphy to residue fields. Its fibres are translates of
the trivial kernel, hence one reduced point.
\end{proof}

\begin{corollary}[Base change for equivariant sheaves]
\label{mumford-cor-quotient-sheaf-base-change}
\dcref{M:ch3:III.12}
\uses{mumford-thm-finite-groupscheme-quotient}
If $Y=X/G$ and $\mathcal G$ is a coherent $G$-sheaf on $X$, then
\[
\pi^*(\pi_*\mathcal G)\simeq\mathcal G\otimes_kR,
\qquad G=\operatorname{Spec}R.
\]
\source{mumford-abelian-varieties:page-0129}
\source{mumford-abelian-varieties:page-0130}
\source{mumford-abelian-varieties:page-0131}
\end{corollary}
\begin{proof}
Affine base change gives the natural pullback isomorphism. Identifying the
two pullbacks through $G\times X\simeq X\times_YX$ and using the action
identifies it with $\mathcal G\otimes_kR$.
\end{proof}





\section{Finite-fibre associated spaces}
\label{mumford-III12-associated-source}
\dcref{M:ch3:III.12}

\begin{definition}[Fibration with finite fibre]
\label{mumford-def-associated-finite-fibre}
\dcref{M:ch3:III.12}
Let a finite group scheme $G$ act freely on $X$, with quotient $X/G$, and
let $F$ be a finite scheme with a $G$-action. The induced free action on
$X\times F$ has quotient
\[
U=(X\times F)/G,
\]
and the natural morphism $\pi:U\to V=X/G$ is called the fibration with
fibre $F$ associated to the principal $G$-bundle $X\to X/G$. It is finite
and flat; its degree is the rank of $\pi_*\mathcal O_U$ over
$\mathcal O_V$.
\source{mumford-abelian-varieties:page-0132}
\uses{mumford-thm-finite-groupscheme-quotient}
\end{definition}

\begin{theorem}[Euler characteristic of an associated fibration]
\label{mumford-thm-euler-associated-fibration}
\dcref{M:ch3:III.12}
\uses{mumford-def-associated-finite-fibre}
If $\pi:U\to V$ is a finite-fibre fibration associated to a principal
$G$-bundle, then for every coherent sheaf $\mathcal F$ on $V$,
\[
\chi(\pi^*\mathcal F)=(\deg\pi)\chi(\mathcal F).
\]
\source{mumford-abelian-varieties:page-0132}
\source{mumford-abelian-varieties:page-0133}
\end{theorem}
\begin{proof}
It is enough to treat the case $V=U/G$ for a free action, since
$(X\times F)\to(X\times F)/G\to X/G$ reduces the general case to the
composite and first morphism. Suppose the assertion fails, and choose a
counterexample $\mathcal F$ minimal by support. Let $\mathcal J$ annihilate
$\mathcal F$ and write $V'$ for its support, $U'=\pi^{-1}(V')$. The quotient
proposition shows that $U'\to V'$ remains a principal $G$-space. Thus we
may assume the assertion holds for every coherent sheaf with proper support.
Exact sequences and flatness then show it also holds for extensions whenever
it holds for two terms.

If $V$ is reducible, a short exact sequence with both terms supported on
proper closed subsets gives a contradiction. If the nilpotent ideal
$\mathcal J$ of $V$ is nonzero, the exact sequence
\[
0\to\mathcal J\mathcal F\to\mathcal F\to
\mathcal F/\mathcal J\mathcal F\to0
\]
does the same. Hence assume $V$ reduced and irreducible. If $r$ is the
generic rank of $\mathcal F$, there is an ideal $\mathcal J$ and an
injection $\mathcal F^r\to\mathcal F$ with proper-support cokernel.
Consequently it suffices to prove the formula for $\mathcal O_V$.

Apply it to $\pi_*\mathcal O_U$, a coherent sheaf of nonzero rank. By the
projection formula,
\[
\begin{aligned}
\chi(\pi^*\pi_*\mathcal O_U)
 &=\chi(\mathcal O_V\otimes_{\mathcal O_V}\pi_*\mathcal O_U)\\
 &=(\deg\pi)\chi(\mathcal O_V)
 =(\deg\pi)\chi(\pi_*\mathcal O_U),
\end{aligned}
\]
which proves the assertion.
\end{proof}

\begin{remark}[Finite étale maps as associated spaces]
\label{mumford-rem-symmetric-associated-space}
\dcref{M:ch3:III.12}
Every finite étale morphism $f:U\to V$ of constant degree $n$ is an
associated finite-fibre fibration for a principal $\Sigma(n)$-space. In the
$n$-fold fibre product $U\times_V\cdots\times_VU$, let $P$ be the open and
closed locus of tuples with pairwise distinct entries. Then $P\to V$ is a
principal $\Sigma(n)$-space. If $F$ is the reduced $n$-point scheme with
the natural permutation action, the invariant map
\[
P\times F\longrightarrow V,
\qquad ((x_1,\ldots,x_n),i)\longmapsto x_i
\]
has quotient $V$ and identifies the associated space with $U$.
\source{mumford-abelian-varieties:page-0133}
\source{mumford-abelian-varieties:page-0134}
\uses{mumford-thm-euler-associated-fibration}
\end{remark}

\section{The dual abelian variety in any characteristic}
\label{mumford-III13-source}
\dcref{M:ch3:III.13}

\begin{definition}[Scheme-theoretic stabilizer of a line bundle]
\label{mumford-def-KL}
\dcref{M:ch3:III.13}
For a line bundle $L$ on an abelian variety $X$, put
\[
M=m^*L\otimes p_1^*L^{-1}\otimes p_2^*L^{-1}
\]
on $X\times X$. The group scheme $K(L)\subset X$ is the maximal closed
subscheme for which $M|_{K(L)\times X}$ is trivial. Equivalently, for every
scheme $S$ and $f:S\to X$, one has $f\in K(L)(S)$ exactly when
\[
T_f^*L_S\simeq L_S\otimes p_2^*N
\]
for a line bundle $N$ on $S$.
\source{mumford-abelian-varieties:page-0134}
\source{mumford-abelian-varieties:page-0135}
\end{definition}
\begin{proof}
The composite $X\times S\xrightarrow{T_f}X\times S\to X$ is
$m\circ(1_X\times f)$, so
$T_f^*L_S\simeq(1_X\times f)^*m^*L$. Restricting a putative isomorphism
to $\{0\}\times S$ identifies $N$ with $f^*L$. Hence the displayed
condition is equivalent to triviality of $(1_X\times f)^*M$, which is the
defining universal property of $K(L)$. In particular $K(L)$ is a subgroup
scheme of $X$.
\end{proof}

\begin{construction}[Dual quotient and normalized Poincare bundle]
\label{mumford-thm-dual-any-characteristic}
\label{mumford-prop-abelian-quotient}
\dcref{M:ch3:III.13}
\uses{mumford-def-KL,mumford-prop-maximal-triviality-scheme,
 mumford-thm-finite-groupscheme-quotient}
Choose an ample line bundle $L$ on $X$. Then $K(L)$ is finite. The quotient
\[
\pi:X\longrightarrow\widehat X=X/K(L)
\]
is an abelian variety. The bundle $M$ above admits a canonical
$K(L)$-linearization and descends uniquely to a normalized line bundle $P$ on
$\widehat X\times X$. Its restrictions to $\{0\}\times X$ and
$\widehat X\times\{0\}$ are trivial, and
\[
\widehat X\xrightarrow{\sim}\operatorname{Pic}^0X
\]
identifies the fibre of $P$ over $\alpha$ with the corresponding algebraically
trivial line bundle on $X$.
\source{mumford-abelian-varieties:page-0135}
\source{mumford-abelian-varieties:page-0136}
\end{construction}
\begin{proof}
For $x\in K(L)(S)$, write $T_x^*L_S\simeq L_S\otimes L_0$ with $L_0$ from
$S$. Then translation by $(x,0)$ preserves $M_S$. Any two lifts to $M_S$
differ by a global unit; the restriction map from $X_S\times_SX_S$ to
$X_S\times_S\{0\}$ is an isomorphism on units. Rigidifying along the second
factor therefore selects a unique lift, and these lifts form a group action.
Faithfully flat descent for the finite quotient gives $P$ and its uniqueness.
The map $X\to\operatorname{Pic}^0X$, $x\mapsto T_x^*L\otimes L^{-1}$, is
constant on $K(L)$ and has kernel $K(L)$, so the induced map from $\widehat X$
is the displayed isomorphism.
\end{proof}

\begin{theorem}[Universal Poincare mapping property]
\label{mumford-thm-poincare-universal-mapping}
\dcref{M:ch3:III.13}
\uses{mumford-prop-maximal-triviality-scheme,mumford-cor-structure-sheaf-cohomology}
Let $S$ be a scheme and $L$ a line bundle on $S\times X$, trivial on
$S\times\{0\}$, whose restriction to every fibre $\{s\}\times X$ lies in
$\operatorname{Pic}^0X$. There is a unique morphism $\phi:S\to\widehat X$
such that $L\simeq(\phi\times1_X)^*P$.
\source{mumford-abelian-varieties:page-0136}
\source{mumford-abelian-varieties:page-0137}
\source{mumford-abelian-varieties:page-0138}
\source{mumford-abelian-varieties:page-0139}
\source{mumford-abelian-varieties:page-0140}
\end{theorem}
\begin{proof}
Put $M=p_{23}^*P\otimes p_{13}^*L^{-1}$ on
$S\times\widehat X\times X$ and let $\Gamma_S$ be its maximal triviality
subscheme. Uniqueness and existence reduce to proving
$\Gamma_S\to S$ is an isomorphism. By localization and base change assume
$S=\operatorname{Spec}B$ is finite local and twist $L$ so its closed fibre
is trivial. The direct images along $S\times\widehat X\times X\to S\times X$
have discrete support, so Leray gives free $B$-modules
\[
H^p(S\times\widehat X\times X,M)
\simeq H^0(S\times X,R^pp_{13,*}M).
\]
The direct images along $S\times\widehat X\times X\to S\times\widehat X$
are supported at $(s,0)$ and are computed by a finite free complex
$0\to K_0\to\cdots\to K_g\to0$ over
$A=B\otimes_k\mathcal O_{0,\widehat X}$.

We use the following regular-local-ring lemma: if $\mathcal O$ is regular of
dimension $g$ and a length-$g$ complex of finite free modules has artinian
cohomology, then $H^i=0$ for $i<g$. For $g>0$, choose
$x\in\mathfrak M\setminus\mathfrak M^2$, reduce the complex modulo $x$,
and use the long exact cohomology sequence and induction on $g$; Nakayama
then gives the vanishing. Applying the lemma and its dual to the complex
above gives an artinian terminal module $K\simeq A/\mathfrak Q$, with
$\mathfrak Q\cap B=0$. For every $\mathfrak M$-primary ideal $\mathfrak b$,
\[
H^0(V(\mathfrak b)\times X,M)
\simeq\operatorname{Hom}_A(A/\mathfrak Q,A/\mathfrak b).
\]
The evaluation map is surjective after reduction at the closed point, hence
$M$ is trivial over $V(\mathfrak Q)\times X$ and
$\Gamma_S=V(\mathfrak Q)$. Its fibre is the reduced point $(s,0)$, so
$A/(\mathfrak Q+\mathfrak M_A)=k$ and $B\to A/\mathfrak Q$ is an
isomorphism. Thus $\Gamma_S\to S$ is an isomorphism, proving the universal
mapping property.
\end{proof}

\begin{corollary}[Cohomology of the Poincare bundle]
\label{mumford-cor-poincare-cohomology}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping}
For an abelian variety $X$ of dimension $g$ and its dual $\widehat X$,
\[
H^i(\widehat X\times X,P)=
\begin{cases}0&i\ne g,\\ k&i=g.\end{cases}
\]
\source{mumford-abelian-varieties:page-0140}
\source{mumford-abelian-varieties:page-0141}
\end{corollary}
\begin{proof}
With $S=\operatorname{Spec}k$ and the trivial bundle in the universal
mapping proof, the resulting complex is a free resolution of $k$ over the
regular local ring $\mathcal O_{0,\widehat X}$. Comparing it with the
Koszul resolution on a basis $x_1,\ldots,x_g$ of the maximal ideal modulo
its square gives the asserted cohomology. Explicitly, the Koszul differential
is
\[
d_p(e_{i_1}\wedge\cdots\wedge e_{i_p})=
\sum_{j=1}^p(-1)^j x_{i_j}e_{i_1}\wedge\cdots\widehat e_{i_j}\cdots\wedge e_{i_p}.
\]
\end{proof}

\begin{corollary}[Structure-sheaf cohomology]
\label{mumford-cor-structure-sheaf-cohomology}
\dcref{M:ch3:III.13}
\uses{mumford-cor-poincare-cohomology}
For $\dim X=g$,
\[
\dim_kH^p(X,\mathcal O_X)=\binom gp.
\]
\source{mumford-abelian-varieties:page-0141}
\end{corollary}
\begin{proof}
The cohomology is that of the Koszul complex tensored with $k$; all its
differentials vanish, and the rank of its $p$-cochains is $\binom gp$.
\end{proof}

\begin{corollary}[Tangent space of the dual]
\label{mumford-cor-tangent-dual-h1}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping}
There is a canonical isomorphism
$T_0\widehat X\simeq H^1(X,\mathcal O_X)$.
\source{mumford-abelian-varieties:page-0141}
\source{mumford-abelian-varieties:page-0142}
\end{corollary}
\begin{proof}
For $S=\operatorname{Spec}k[\epsilon]/(\epsilon^2)$, the universal property
identifies $T_0\widehat X$ with the kernel of restriction from line bundles
on $S\times X$ trivial on the closed fibre. The exact sequence
\[
1\to1+\epsilon\mathcal O_X\to\mathcal O_{S\times X}^*\to
\mathcal O_X^*\to1,
\qquad1+\epsilon\mathcal O_X\simeq\mathcal O_X,
\]
gives the result.
\end{proof}

\begin{corollary}[Dual isogenies]
\label{mumford-cor-dual-isogeny-degree}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping,mumford-thm-euler-associated-fibration}
If $f:X\to Y$ is an isogeny, there is a unique homomorphism
$\widehat f:\widehat Y\to\widehat X$ with
\[
(1\times\widehat f)^*P_X\simeq(f\times1)^*P_Y,
\]
and $\deg f=\deg\widehat f$.
\source{mumford-abelian-varieties:page-0141}
\source{mumford-abelian-varieties:page-0142}
\end{corollary}
\begin{proof}
The universal property gives $\widehat f$. Applying the Euler
characteristic formula for a finite flat associated fibre space to the two
pullbacks gives
\[
\chi((1\times\widehat f)^*P_X)=\deg\widehat f\,\chi(P_X),\qquad
\chi((f\times1)^*P_Y)=\deg f\,\chi(P_Y).
\]
Since both Poincare bundles have Euler characteristic $(-1)^g$, the degrees
are equal.
\end{proof}

\begin{corollary}[The morphism associated to a line bundle]
\label{mumford-cor-line-bundle-morphism}
\label{mumford-prop-phi-L}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping,mumford-prop-maximal-triviality-scheme}
For every line bundle $L$ on $X$, $\phi_L:X\to\operatorname{Pic}^0X\simeq
\widehat X$ is a morphism and its scheme-theoretic kernel is $K(L)$.
\source{mumford-abelian-varieties:page-0142}
\end{corollary}
\begin{proof}
The universal property applied to
$m^*L\otimes p_1^*L^{-1}\otimes p_2^*L^{-1}$ gives the morphism. The
definition of $K(L)$ as the maximal subscheme on which this bundle is
trivial is exactly the scheme-theoretic kernel.
\end{proof}

\begin{proposition}[Divisorial correspondences]
\label{mumford-prop-divisorial-correspondence}
\dcref{M:ch3:III.13}
\uses{mumford-thm-poincare-universal-mapping,mumford-thm-euler-associated-fibration}
Let $Q$ be a line bundle on $X\times Y$, with trivial restrictions to the
two coordinate factors, and $\dim X=\dim Y$. The following are equivalent:
\begin{enumerate}
\item no nonzero subscheme of $X$ makes $Q$ trivial;
\item no nonzero subscheme of $Y$ makes $Q$ trivial;
\item $|\chi(Q)|=1$.
\end{enumerate}
When they hold, $Y\simeq\widehat X$ and $X\simeq\widehat Y$.
\source{mumford-abelian-varieties:page-0142}
\source{mumford-abelian-varieties:page-0143}
\end{proposition}
\begin{proof}
The universal property gives $f:Y\to\widehat X$ with
$Q=(1_X\times f)^*P$. Condition (2) says that $f$ has trivial kernel. Equal
dimensions then make $f$ an isogeny, and
$|\chi(Q)|=\deg f\,|\chi(P)|=\deg f$. Conversely, if $f$ has positive
dimensional kernel, finite subgroups of arbitrarily large order $d$ in the
kernel make $Q$ descend through $X\times Y/F$, so the Euler characteristic
is divisible by every such $d$ and is zero. This proves the equivalence.
\end{proof}

\begin{corollary}[Duality hypothesis]
\label{mumford-thm-duality-hypothesis}
\label{mumford-prop-biduality-any-characteristic}
\dcref{M:ch3:III.13}
The canonical morphism $X\to\widehat{\widehat X}$ defined by the Poincare
bundle is an isomorphism.
\source{mumford-abelian-varieties:page-0143}
\uses{mumford-prop-divisorial-correspondence}
\end{corollary}
\begin{proof}
The Poincare bundle satisfies condition (2) of the preceding proposition,
and hence also (1), so the induced morphism is an isomorphism.
\end{proof}

\section{Duality of finite commutative group schemes}
\label{mumford-III14-source}
\dcref{M:ch3:III.14}

\begin{definition}[Cartier dual]
\label{mumford-def-cartier-dual}
\dcref{M:ch3:III.14}
For a finite commutative group scheme $G=\operatorname{Spec}R$ in
characteristic $p>0$, the dual group scheme is
$\widehat G=\operatorname{Spec}R^*$, where the dual of the group-law
coproduct is the multiplication on $R^*$ and the dual of multiplication on
$R$ is its coproduct.
\source{mumford-abelian-varieties:page-0143}
\source{mumford-abelian-varieties:page-0144}
\end{definition}

\begin{theorem}[Cartier dual represents characters]
\label{mumford-thm-cartier-duality}
\dcref{M:ch3:III.14}
\uses{mumford-def-cartier-dual}
For every scheme $S$,
\[
\widehat G(S)\simeq\operatorname{Hom}_S(G_S,\mathbb G_{m,S}),
\]
functorially in $S$.
\source{mumford-abelian-varieties:page-0144}
\source{mumford-abelian-varieties:page-0145}
\source{mumford-abelian-varieties:page-0146}
\end{theorem}
\begin{proof}
For $S=\operatorname{Spec}A$, a homomorphism to $\mathbb G_m$ is an
$\alpha\in R\otimes A$ satisfying
$\mu_R(\alpha)=\alpha\otimes\alpha$ and $\epsilon(\alpha)=1$.
The latter condition implies invertibility, using the inverse map. Since
$R\otimes A\simeq\operatorname{Hom}_A((R\otimes A)^*,A)$, these elements
are precisely algebra homomorphisms $A^*\otimes A\to A$, i.e. $A$-points of
$\operatorname{Spec}R^*$. The construction is natural and respects group
laws. Taking $S=\widehat G$ gives the universal bilinear character
$\widehat G\times G\to\mathbb G_m$.
\end{proof}

\begin{proposition}[Local/reduced decomposition]
\label{mumford-prop-cartier-local-reduced}
\dcref{M:ch3:III.14}
\uses{mumford-thm-cartier-duality}
Every finite commutative group scheme has a unique product decomposition
$G_{r,r}\times G_{r,l}\times G_{l,r}\times G_{l,l}$ according as it and
its Cartier dual are reduced or local. Groups of type $(r,r)$ are products
of cyclic groups of order prime to $p$; groups of type $(r,l)$ are products
of cyclic $p$-groups and type $(l,r)$ are their duals.
\source{mumford-abelian-varieties:page-0147}
\end{proposition}
\begin{proof}
If $G$ is reduced, it is uniquely expressible as a product $G_1\times G_2$,
where $G_1$ has order prime to $p$ and $G_2$ is a $p$-group. By duality,
$\widehat G_1$ is reduced and $\widehat G_2$ is local. When $G$ is local,
splitting $\widehat G$ into local and reduced parts and dualizing back proves
the analogous assertion. The only groups of type $(r,r)$ are reduced groups
of order prime to $p$, hence products of cyclic prime-power groups with
primes distinct from $p$. The only groups of type $(r,l)$ are $p$-groups,
hence products of $\mathbb Z/p^{n_i}\mathbb Z$'s; the groups of type $(l,r)$
are their duals. Applying these decompositions to the four possible types
gives the asserted unique product decomposition.
\end{proof}

\begin{proposition}[Primitive elements and the Lie algebra]
\label{mumford-prop-cartier-primitives}
\dcref{M:ch3:III.14}
\uses{mumford-thm-cartier-duality,mumford-prop-group-scheme-lie}
\[
\operatorname{Hom}_{\mathrm{Gp.Sch}}(\widehat G,\mathbb G_a)
\simeq\{\alpha\in R^*:s^*\alpha=\alpha\otimes1+1\otimes\alpha\}
\simeq\Lie(G).
\]
The $p$-power operation corresponds to composition with Frobenius.
\source{mumford-abelian-varieties:page-0148}
\source{mumford-abelian-varieties:page-0149}
\end{proposition}
\begin{proof}
For $\alpha(1)=0$ and $\alpha(\mathfrak M^2)=0$, the transpose of $\alpha$
is a derivation. Primitive elements are exactly these invariant derivations,
and the coproduct calculation gives the displayed bijections.
\end{proof}

\begin{definition}[Height one]
\label{mumford-def-height-one-group}
\dcref{M:ch3:III.14}
A finite group scheme is of height one if it has one point $e$ and
$x^p=0$ for every $x$ in the maximal ideal at $e$.
\source{mumford-abelian-varieties:page-0150}
\end{definition}

\begin{theorem}[Height-one group schemes and $p$-Lie algebras]
\label{mumford-thm-height-one-equivalence}
\dcref{M:ch3:III.14}
\uses{mumford-prop-cartier-primitives}
The functor $G\mapsto\Lie G$ is an equivalence between finite commutative
height-one group schemes and finite-dimensional $p$-Lie algebras.
\source{mumford-abelian-varieties:page-0150}
\source{mumford-abelian-varieties:page-0151}
\source{mumford-abelian-varieties:page-0152}
\end{theorem}
\begin{proof}
For a $p$-Lie algebra $\mathfrak g$, set
$U(\mathfrak g)=S(\mathfrak g)/\langle\alpha^{(p)}-\alpha^p\rangle$ and
$G(\mathfrak g)=\operatorname{Spec}U(\mathfrak g)^*$. The coproduct
$s(\alpha)=1\otimes\alpha+\alpha\otimes1$ makes this a finite group
scheme of height one. Primitive elements identify its Lie algebra with
$\mathfrak g$. Conversely, the inclusion $\Lie G\to R^*$ extends to a
bialgebra map $U(\Lie G)\to R^*$; its transpose is a group morphism.
The differential is an isomorphism, hence the morphism is a closed immersion
by Nakayama, and both coordinate rings have dimension
$p^{\dim\Lie G}$, so it is an isomorphism.
\end{proof}

\begin{corollary}[Actions of height-one groups]
\label{mumford-cor-height-one-actions}
\dcref{M:ch3:III.14}
\uses{mumford-thm-height-one-equivalence}
For a commutative height-one $G$ with Lie algebra $\mathfrak g$, an action on
$X$ is equivalent to derivations $D_\alpha$ satisfying
\[
[D_\alpha,D_\beta]=0,\qquad D_{\alpha^{(p)}}=D_\alpha^p.
\]
Moreover multiplication by $p$ on $G$ is zero.
\source{mumford-abelian-varieties:page-0152}
\source{mumford-abelian-varieties:page-0153}
\end{corollary}
\begin{proof}
The relations define a homomorphism from $U(\mathfrak g)$ to differential
operators. Transposing it gives
$\mathcal O_X\to R\otimes\mathcal O_X$; the unit and composition diagrams
are exactly the action diagrams. The assertion about multiplication by $p$
follows because it kills the Lie algebra and the height-one equivalence is
faithful.
\end{proof}

\begin{corollary}[Semisimple/nilpotent decomposition]
\label{mumford-cor-p-lie-semisimple-nilpotent}
\dcref{M:ch3:III.14}
\uses{mumford-thm-height-one-equivalence}
Any vector space with a $p$-linear operation decomposes uniquely as
$V=V_s\oplus V_n$, with a basis of fixed vectors on $V_s$ and nilpotent
$p$-operation on $V_n$. For a height-one group this is the decomposition
$\Lie G_{l,r}\oplus\Lie G_{l,l}$.
\source{mumford-abelian-varieties:page-0153}
\source{mumford-abelian-varieties:page-0154}
\end{corollary}
\begin{proof}
For a height-one group scheme, the local/reduced decomposition gives
\[
G=G_{l,r}\times G_{l,l}.
\]
Both factors are again of height one. Since $G_{l,r}$ is killed by $p$, it
is isomorphic to $\mu_p^n$ for some $n$. As $\Lie(\mu_p)$ has a generator
$e$ with $e^{(p)}=e$, the induced decomposition
\[
\Lie G=\Lie G_{l,r}\oplus\Lie G_{l,l}=\mathfrak g_1\oplus\mathfrak g_2
\]
gives a basis $e_1,\ldots,e_n$ of $\mathfrak g_1$ with
$e_i^{(p)}=e_i$. Since $G_{l,l}$ is local and $\mathfrak g_2$ is contained
in the maximal ideal of $\Gamma(\mathcal O_{G_{l,l}})$, every
$\alpha\in\mathfrak g_2$ satisfies $\alpha^{(p^m)}=0$ for $m$ sufficiently
large. Thus the displayed decomposition is invariant under the $p$-linear
operation, with the first summand having a basis of fixed vectors and the
second having nilpotent $p$-operation. The height-one equivalence identifies
these summands with $\Lie G_{l,r}$ and $\Lie G_{l,l}$, respectively; the
uniqueness follows from the corresponding uniqueness of the group-scheme
decomposition.
\end{proof}

\section{Applications to abelian varieties}
\label{mumford-III15-source}
\dcref{M:ch3:III.15}

\begin{theorem}[Kernel of the dual isogeny]
\label{mumford-thm-dual-isogeny-kernel}
\dcref{M:ch3:III.15}
\uses{mumford-thm-cartier-duality,mumford-prop-translation-quotient-isogeny}
If $f:X\to Y$ is an isogeny with kernel $K$ and dual map
$\widehat f:\widehat Y\to\widehat X$ with kernel $K'$, then
$K'\simeq\widehat K$ canonically.
\source{mumford-abelian-varieties:page-0154}
\source{mumford-abelian-varieties:page-0155}
\source{mumford-abelian-varieties:page-0156}
\end{theorem}
\begin{proof}
For a line bundle $L$ on $Y$,
\[
\phi_{f^*L}(x)=\widehat f(\phi_L(f(x))).
\]
Thus $\widehat K(S)$ is the kernel of pullback between families of line
bundles on $S\times Y$ and $S\times X$. Since $S\times Y$ is the quotient
of $S\times X$ by the free action of $K$, these are liftings of the action
to $S\times X\times\mathbb A^1$. Completeness of $X$ makes a linear lift
independent of $x$, so it has the form
\[
k:(s,x,\alpha)\longmapsto(s,x+k,\chi(k,s)\alpha)
\]
for a character $\chi:K\times S\to\mathbb G_m$. Cartier duality identifies
these with $\widehat K(S)$, naturally in $S$.
\end{proof}

\begin{definition}[Height-one isogeny]
\label{mumford-def-height-one-isogeny}
\dcref{M:ch3:III.15}
\uses{mumford-def-height-one-group}
An isogeny $f:X\to Y$ is of height one if $k(X)^p\subset k(Y)$.
This is equivalent to its kernel being a height-one group scheme.
\source{mumford-abelian-varieties:page-0156}
\end{definition}
\begin{proof}
For a height-one isogeny, integral closure gives
$\mathcal O_{Y,0}\supset\{a^p:a\in\mathcal O_{X,0}\}$, so the kernel has
height one. Conversely, invariants of the height-one kernel on affine opens
are exactly the functions coming from $Y$.
\end{proof}

\begin{theorem}[Height-one isogenies and $p$-Lie subalgebras]
\label{mumford-thm-height-one-isogeny}
\dcref{M:ch3:III.15}
\uses{mumford-thm-height-one-equivalence}
Height-one isogenies out of $X$, up to isomorphism, correspond one-to-one to
$p$-Lie subalgebras of $\Lie X$.
\source{mumford-abelian-varieties:page-0157}
\end{theorem}
\begin{proof}
Such isogenies are determined by their height-one kernels, which are
subgroup schemes of $X_p$. The height-one equivalence identifies these with
$p$-Lie subalgebras of $\Lie X_p=\Lie X$.
\end{proof}

\begin{theorem}[Frobenius and the Hasse--Witt operation]
\label{mumford-thm-lie-dual-frobenius}
\dcref{M:ch3:III.15}
\uses{mumford-cor-tangent-dual-h1}
Under $\Lie\widehat X\simeq H^1(X,\mathcal O_X)$, the $p$-power operation
on $\Lie\widehat X$ is the Frobenius map on $H^1(X,\mathcal O_X)$.
\source{mumford-abelian-varieties:page-0158}
\source{mumford-abelian-varieties:page-0159}
\source{mumford-abelian-varieties:page-0160}
\source{mumford-abelian-varieties:page-0161}
\end{theorem}
\begin{proof}
For $D$ represented by an infinitesimal automorphism over
$k[\epsilon]/(\epsilon^2)$, take $p$ copies over
$k[\epsilon_1,\ldots,\epsilon_p]/(\epsilon_i^2)$. Their composite is
$1+s_1D+s_2D^2+\cdots+s_pD^p$. Specializing the elementary symmetric
functions by $s_1\mapsto0$, $s_p\mapsto\epsilon$ gives $D^{(p)}$.
For a group scheme this is translation by the $p$-power of the tangent
point. A tangent vector of the dual represented by a cocycle
$\{1+\epsilon f_{ij}\}$ therefore has $p$-power represented by
$\{1+\epsilon f_{ij}^p\}$, exactly Frobenius on $H^1(X,\mathcal O_X)$.
\end{proof}

\section{Cohomology of line bundles}
\label{mumford-III16-source}
\dcref{M:ch3:III.16}

\begin{theorem}[Riemann--Roch]
\label{mumford-thm-riemann-roch}
\dcref{M:ch3:III.16}
\uses{mumford-prop-degree-hilbert,mumford-thm-cube-varieties}
For $L\simeq\mathcal O_X(D)$ on a $g$-dimensional abelian variety,
\[
\chi(L)=\frac{(D^g)}{g!},\qquad \chi(L)^2=\deg\phi_L.
\]
\source{mumford-abelian-varieties:page-0161}
\source{mumford-abelian-varieties:page-0162}
\source{mumford-abelian-varieties:page-0163}
\end{theorem}
\begin{proof}
Twisting by $\operatorname{Pic}^0X$ does not change Euler characteristic.
For symmetric $L$, $n_X^*(L^m)\simeq L^{mn^2}$, so homogeneity gives
$\chi(L^n)=a(L)n^g/g!$. For very ample $L_i=\mathcal O(D_i)$, the polynomial
$g!\chi(L_1^{n_1}\otimes L_2^{n_2})$ equals
$((n_1D_1+n_2D_2)^g)$; taking $n_1=1,n_2=-1$ yields the first formula.

If $K(L)$ is finite, pullback of the Poincare bundle gives
\[
\chi(m^*L\otimes p_1^*L^{-1}\otimes p_2^*L^{-1})=(-1)^g\chi(L)^2.
\]
The quotient $X\times X\to X\times\widehat X$ has degree $\deg\phi_L$,
so the same expression is $(-1)^g\deg\phi_L$. If $K(L)$ is not finite,
 finite subgroups of arbitrarily large order force both quantities to vanish.
\end{proof}

\begin{remark}[Analytic degree and Pfaffian]
\label{mumford-source-pfaffian-degree}
\dcref{M:ch3:III.16}
Over $\mathbf C$, for $L=L(H,\alpha)$ with $K(L)$ finite,
\[
 \deg\phi_L=\operatorname{order}K(L)
 =\operatorname{order}(U^\perp/U)=\det(E(u_i,u_j)),
 \qquad |\chi(L)|=\sqrt{\det(E(u_i,u_j))}.
\]
Thus $|\chi(L)|$ is the Pfaffian of the skew matrix $(E(u_i,u_j))$ up to
sign, since $\operatorname{pf}(A)^2=\det A$.
\source{mumford-abelian-varieties:page-0165}
\end{remark}

\begin{theorem}[Vanishing and index]
\label{mumford-thm-line-bundle-index}
\dcref{M:ch3:III.16}
\uses{mumford-thm-riemann-roch,mumford-thm-cube-varieties}
If $K(L)$ is finite, there is a unique $i(L)$ with
$H^p(X,L)=0$ for $p\ne i(L)$ and $H^{i(L)}(X,L)\ne0$, and
$i(L^{-1})=g-i(L)$.
\source{mumford-abelian-varieties:page-0161}
\source{mumford-abelian-varieties:page-0164}
\end{theorem}
\begin{proof}
The Cartesian diagram for $1\times\phi_L$ and flatness gives
\[
\dim H^q(X\times X,m^*L\otimes p_1^*L^{-1})=
\begin{cases}0&q\ne g,\\\deg\phi_L&q=g.\end{cases}
\]
Kunneth therefore gives
\[
\sum_{i=0}^qh^i(L)h^{q-i}(L^{-1})=
\begin{cases}0&q\ne g,\\\deg\phi_L&q=g.\end{cases}
\]
Nonnegativity forces exactly one nonzero group on each side and their
indices sum to $g$.
\end{proof}

\begin{lemma}[Polynomial growth of cohomology]
\label{mumford-lem-index-growth}
\dcref{M:ch3:III.16}
For a projective $r$-fold and line bundles $L_1,\ldots,L_k$, there is $c$
such that
\[
\dim H^i(L_1^{a_1}\otimes\cdots\otimes L_k^{a_k})
<c(1+|a|^r).
\]
\source{mumford-abelian-varieties:page-0166}
\source{mumford-abelian-varieties:page-0167}
\source{mumford-abelian-varieties:page-0168}
\end{lemma}
\begin{proof}
Twist by a sufficiently ample bundle to reduce to very ample bundles and
induct on $\dim X+k$. A hyperplane-section exact sequence compares the
cohomology for consecutive exponents with cohomology on a variety of
dimension $r-1$. The inductive bound is $c(1+|a|^{r-1})$; summing over the
exponent gives the asserted $c'(1+|a|^r)$, with negative exponents handled
by the reversed exact sequence.
\end{proof}

\begin{theorem}[Index polynomial]
\label{mumford-thm-index-polynomial}
\dcref{M:ch3:III.16}
If $L$ is ample and $M$ non-degenerate on a $g$-fold, the polynomial
$P(t)=\chi(L^t\otimes M)$ has all roots real, and $i(M)$ is the number of
positive roots counted with multiplicity.
\source{mumford-abelian-varieties:page-0166}
\source{mumford-abelian-varieties:page-0168}
\source{mumford-abelian-varieties:page-0169}
\source{mumford-abelian-varieties:page-0170}
\source{mumford-abelian-varieties:page-0171}
\uses{mumford-lem-index-growth,mumford-thm-line-bundle-index}
\end{theorem}
\begin{proof}
Step A: if $P(1,t)\ne0$ for $0<t<1$, then
$i(L)=i(L\otimes H)$. Otherwise choose the first exponent at which the
index changes. The hyperplane exact sequence gives cohomology on a
dimension $g-1$ section at least $N^gP(1,a/N)$, contradicting the growth
lemma as $N$ tends to infinity.

Step B: for $F(s,t)=\chi(L_1^s\otimes L_2^t)$, nonvanishing of
$F(t,1-t)$ on $(0,1)$ and Step A applied after inserting a very ample $L_3$
give equality of the indices of $L_1$ and $L_2$.

Step C: if all three of $L_1,L_2,L_1\otimes L_2$ are non-degenerate, apply
the map $(x,y)\mapsto x-y$ and Leray to obtain
$i(L_1\otimes L_2)\le i(L_1)+i(L_2)$. Step D compares the indices along a
segment whose Euler polynomial has a unique zero of multiplicity $\lambda$;
the hyperplane exact sequences and the growth lemma give
\(0<i(L_2)-i(L_1)\le\lambda\).

For completeness, the final induction in the source takes hyperplane powers
$H^\alpha$ and proves
\[
H^p(H^\alpha,L_1^k\otimes L_2^l)=0\quad(p<i_2-\alpha-1)
\]
from the exact sequence
\[
0\to L_1^{k-1}\otimes L_2^{l+1}|_{H^{\alpha-1}}
\to L_1^k\otimes L_2^l|_{H^{\alpha-1}}
\to L_1^k\otimes L_2^l|_{H^\alpha}\to0.
\]
The resulting injection and the growth estimate yield
\[
\left|f\left(\frac{r}{N},\frac{s}{N}\right)\right|<\frac{c}{N^{i_2-i_1}},
\qquad
\left|f\left(\frac{r}{N},\frac{s}{N}\right)\right|>\frac{c'}{N^\lambda},
\]
so $i_2-i_1\le\lambda$ and the theorem follows.
\end{proof}

\begin{remark}[Completion of the index root count]
\label{mumford-rem-index-root-count-conclusion}
\dcref{M:ch3:III.16}
\uses{mumford-thm-index-polynomial}
For $P(n,m)=\chi(L^n\otimes M^m)$, choose $q>0$ and integers $r_i$ with
$q^{-1}(r_i-1)<t_i<q^{-1}r_i$, where $t_i$ are the real roots of
$P(t,1)$. By the preceding index comparisons,
\[
i(r_k)\le i(r_k-1)=i(r_{k-1})\le\cdots\le i(r_1-1)=i(0),
\]
and $i(r_i-1)-i(r_i)\le\lambda_i$. For large positive $r$, $i(r)=0$,
and for large negative $r$, $i(r)=g$. Hence
\[
g=i(\text{very negative }r)-i(\text{very positive }r)\le\sum_i\lambda_i.
\]
Since $P$ has degree at most $g$, equality holds; $i(0)=i(M)$ is the sum
of multiplicities of positive roots.
\source{mumford-abelian-varieties:page-0172}
\source{mumford-abelian-varieties:page-0173}
\end{remark}

\begin{corollary}[Complex index and eigenvalues]
\label{mumford-cor-complex-index-negative-eigenvalues}
\dcref{M:ch3:III.16}
\uses{mumford-thm-index-polynomial}
If $X=V/U$ and $L=L(H,\alpha)$ is non-degenerate, then $i(L)$ is the
number of negative eigenvalues of $H$. Choosing an ample
$L_0=L(H_0,\alpha_0)$,
\[
\chi(L_0^n\otimes L)=\operatorname{pf}(nE_0+E),
\qquad E=\operatorname{Im}H.
\]
Diagonalizing relative to $H_0$, $H(e_i,e_j)=\lambda_i\delta_{ij}$, the
Pfaffian is $\prod_i(n+\lambda_i)$, proving the assertion.
\source{mumford-abelian-varieties:page-0173}
\source{mumford-abelian-varieties:page-0174}
\end{corollary}

\section{Very ample line bundles}
\label{mumford-III17-source}
\dcref{M:ch3:III.17}

\begin{theorem}[Very ampleness of powers]
\label{mumford-thm-high-power-very-ample}
\dcref{M:ch3:III.17}
\uses{mumford-thm-index-polynomial,mumford-cor-complex-index-negative-eigenvalues}
For any ample line bundle $L$ on an abelian variety $X$, $L^n$ is very ample
if $n>3$.
\source{mumford-abelian-varieties:page-0174}
\source{mumford-abelian-varieties:page-0175}
\source{mumford-abelian-varieties:page-0176}
\end{theorem}
\begin{proof}
It suffices to prove the assertion for $L^3$. Choose an effective divisor
$D$ without multiple components. For $x,y\in X$,
\[
T_x^*D+T_y^*D+T_{-x-y}^*D\in|3D|.
\]
We establish: (1) for $x_0\ne x_1$, some $D'\in|3D|$ contains $x_0$ but
not $x_1$; (2) every tangent vector at $x_0$ is separated by some
$D'\in|3D|$. By translation assume $x_0=0$.

If (1) failed, then $\operatorname{Supp}D=\operatorname{Supp}D-x_1$, so
$x_1\in K(L)$. Quotienting by the finite group generated by $x_1$ and
comparing dimensions of sections gives a contradiction. Thus (1) holds.

If (2) failed for a nonzero tangent vector $t$, the invariant vector field
$T$ would be tangent to $D$ everywhere. Locally, $T(\phi)=\alpha\phi$.
In characteristic $0$ this forces $t=0$. In characteristic $p$, let
$H\subset K(L)$ be the smallest subgroup containing $t$; $D$ is invariant
under translations by $H$.

Let $X'=X/H$, $D'=D/H$. The quotient $\pi:X\to X'$ is flat and
surjective, $D'$ is a divisor, and $D=\pi^*D'$. Thus
\[
\mathcal O_X(-D)\simeq
\mathcal O_{X'}(-D')\otimes_{\mathcal O_{X'}}\mathcal O_X.
\]
Comparing dimensions of sections on $X$ and $X'$ gives a contradiction.
Therefore (2) holds.
\end{proof}

\label{chap:mumford-hom-ladic}



\section{Etale coverings}
\label{mumford-IV18-source}
\dcref{M:ch4:IV.18}

\begin{theorem}[Serre--Lang]
\label{mumford-thm-etale-cover-abelian-structure}
\dcref{M:ch4:IV.18}
If $X$ is an abelian variety, $Y$ a variety, and $f:Y\to X$ an etale
covering, then $Y$ has a unique abelian-variety structure for which $f$ is
a separable isogeny.
\source{mumford-abelian-varieties:page-0178}
\source{mumford-abelian-varieties:page-0179}
\source{mumford-abelian-varieties:page-0180}
\end{theorem}
\begin{proof}
Let $\Gamma_m$ be the graph of multiplication on $X$ and let $\Gamma'$ be
its inverse image in $Y^3$. Let $\Gamma$ be the component containing
$(y_0,y_0,y_0)$, where $f(y_0)=0$. Its projection
$p:\Gamma\to Y\times Y$ is etale. The sections
$\sigma_1(y)=(y_0,y,y)$ and $\sigma_2(y)=(y,y_0,y)$ show that it is enough
to prove $p$ is an isomorphism, or equivalently that the fibre of
$q:\Gamma\to Y$ at $y_0$ is irreducible.

We use the lemma below. Since $\Gamma$ is nonsingular and connected it is
irreducible, and $q$ is proper smooth with a section, so the lemma applies.
Thus $p$ is an isomorphism. The third projection then defines a morphism
$v:Y\times Y\to Y$ with $v(y,y_0)=y=v(y_0,y)$. The appendix theorem on
such a composition makes $Y$ an abelian variety with zero $y_0$; $f$ is a
homomorphism because $f(y_0)=0$.
\end{proof}

\begin{lemma}[Irreducibility of fibres]
\label{mumford-lem-etale-cover-graph}
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure}
If $f:X\to Y$ is a proper smooth morphism of irreducible varieties with a
section, all fibres of $f$ are irreducible.
\source{mumford-abelian-varieties:page-0179}
\end{lemma}
\begin{proof}
Take $Y=\operatorname{Spec}A$ affine and $B=\Gamma(X,\mathcal O_X)$.
The factorization $X\to\operatorname{Spec}B\to Y$ and the section imply,
by equality of dimensions, that $A=B$. Smooth fibres are nonsingular, so it
remains to prove connectedness. A universally computing free complex gives,
after completion at a maximal ideal,
\[
\widehat A\simeq\varprojlim_n\ker\left[
 K_0/\mathfrak M^nK_0\to K_1/\mathfrak M^nK_1\right]
\simeq\varprojlim_n H^0(f^{-1}(y),\mathcal O_X/\mathfrak M^n\mathcal O_X).
\]
If a fibre were $Z_1\cup Z_2$ disconnected, a function reducing to $1$ on
$Z_1$ and $0$ on $Z_2$ would give a nontrivial idempotent in the local ring
$\widehat A$, a contradiction.
\end{proof}

\begin{remark}[Quasi-inverse to an isogeny]
\label{mumford-rem-isogeny-quasi-inverse}
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure}
If $f:Y\to X$ is an isogeny of abelian varieties, there is an isogeny
$g:X\to Y$ and $n>0$ with $g f=n_Y$ and $f g=n_X$: choose $n$ killing
$\ker f$, and factor multiplication by $n$ through the quotient by $\ker f$.
\source{mumford-abelian-varieties:page-0180}
\end{remark}

\begin{proposition}[Fundamental group and Tate modules]
\label{mumford-prop-etale-coverings-av}
\label{mumford-def-tate-module}
\label{mumford-prop-galois-tate-action}
\dcref{M:ch4:IV.18}
\uses{mumford-thm-etale-cover-abelian-structure}
For a pointed nonsingular variety, the pointed connected finite etale
coverings form an inverse system and
\[
\pi_1(X,x_0)=\varprojlim_{(Y,y_0,\pi)}G_Y.
\]
For an abelian variety $X$ with zero base point,
\[
\pi_1(X)\simeq\prod_lT_l(X),\qquad T_l(X)=\varprojlim_mX_{l^m}.
\]
For $l\ne p$, $T_l(X)\simeq\mathbb Z_l^{2g}$; if $r$ is the $p$-rank,
$T_p(X)=\varprojlim X^r_{p^m}\simeq\mathbb Z_p^r$.
\source{mumford-abelian-varieties:page-0180}
\source{mumford-abelian-varieties:page-0181}
\source{mumford-abelian-varieties:page-0182}
\source{mumford-abelian-varieties:page-0183}
\end{proposition}
\begin{proof}
There is at most one pointed map over $X$ between two coverings; when it
exists it induces a unique surjection of their deck groups. For $l\ne p$,
the coverings $X\xrightarrow{l^m}X$ are cofinal among coverings with
$l$-power kernel, giving the inverse limit. The finite torsion groups are
$X_{l^m}\simeq(\mathbb Z/l^m\mathbb Z)^{2g}$. The characteristic-$p$
statement follows from the reduced part of $X_{p^m}$. Over $\mathbb C$,
for $X=V/U$, the same system is $\varprojlim U/l^mU$, whose full profinite
completion is $\varprojlim U/nU$.
\end{proof}

\section{Structure of $\operatorname{Hom}(X,Y)$}
\label{mumford-IV19-source}
\dcref{M:ch4:IV.19}

\begin{definition}[Homomorphisms up to isogeny]
\label{mumford-def-hom-up-to-isogeny}
\dcref{M:ch4:IV.19}
Put
$\operatorname{Hom}^0(X,Y)=\mathbb Q\otimes_\mathbb Z\operatorname{Hom}(X,Y)$
and $\operatorname{End}^0X=\mathbb Q\otimes_\mathbb Z\operatorname{End}X$.
Composition makes abelian varieties up to isogeny a category, in which
isogenies are isomorphisms, and
\[
\operatorname{Hom}^0(X,Y)=\varinjlim_{X'\to X}\operatorname{Hom}(X',Y).
\]
\source{mumford-abelian-varieties:page-0183}
\end{definition}

\begin{theorem}[Poincare complete reducibility]
\label{mumford-thm-poincare-complete-reducibility}
\dcref{M:ch4:IV.19}
\uses{mumford-cor-line-bundle-morphism}
If $Y$ is an abelian subvariety of $X$, there is an abelian subvariety $Z$
with $Y\cap Z$ finite and $Y+Z=X$; equivalently $X$ is isogenous to
$Y\times Z$.
\source{mumford-abelian-varieties:page-0184}
\end{theorem}
\begin{proof}
Let $i:Y\to X$ be inclusion, $\widehat i:\widehat X\to\widehat Y$ its
dual, and choose ample $L$ on $X$. Put $Z$ equal to the connected component
of zero in $\phi_L^{-1}(\ker\widehat i)$. Then
$\dim Z\ge\dim X-\dim Y$, while
$Z\cap Y=K(L|_Y)$ is finite. Therefore $Z\times Y\to X$ is surjective
with finite kernel.
\end{proof}

\begin{definition}[Simple abelian variety]
\label{mumford-def-simple-abelian-variety}
\dcref{M:ch4:IV.19}
An abelian variety is simple if it has no abelian subvariety other than zero
and itself.
\source{mumford-abelian-varieties:page-0185}
\end{definition}

\begin{corollary}[Simple decomposition]
\label{mumford-cor-simple-decomposition}
\label{mumford-cor-simple-endomorphism-algebra}
\dcref{M:ch4:IV.19}
Every abelian variety is isogenous to
$X_1^{n_1}\times\cdots\times X_k^{n_k}$ with the $X_i$ simple and pairwise
non-isogenous; the types and multiplicities are unique. If $X$ is simple,
$\operatorname{End}^0X$ is a division ring, and in general
\[
\operatorname{End}^0(X)=\bigoplus_iM_{n_i}(\operatorname{End}^0X_i).
\]
\source{mumford-abelian-varieties:page-0185}
\uses{mumford-thm-poincare-complete-reducibility}

\notready
\end{corollary}

\begin{theorem}[Degree polynomial]
\label{mumford-thm-degree-polynomial}
\dcref{M:ch4:IV.19}
\uses{mumford-thm-poincare-complete-reducibility,mumford-thm-riemann-roch}
The function $\phi\mapsto\deg\phi$ on $\operatorname{End}X$ extends to a
homogeneous polynomial of degree $2g$ on $\operatorname{End}^0X$.
\source{mumford-abelian-varieties:page-0185}
\source{mumford-abelian-varieties:page-0186}
\end{theorem}
\begin{proof}
For $P(n)=\deg(n\phi+\psi)$, the ample bundle formula gives
$P(n)=\chi((n\phi+\psi)^*L)/\chi(L)$. The theorem of the cube supplies
line bundles $L_1,L_2,L_3$ with
\[
L_{n+2}\otimes L_{n+1}^{-2}\otimes L_n\otimes(2\phi)^*L^{-1}
\otimes\phi^*L\otimes\phi^*L=1,
\]
and induction gives
$L_n=L_1^{n(n-1)/2}\otimes L_2^n\otimes L_3$. Since Euler characteristic
is polynomial on line bundles, $P(n)$ is polynomial; homogeneity follows
from $\deg(n\phi)=n^{2g}\deg\phi$.
\end{proof}

\begin{theorem}[Tate representation]
\label{mumford-thm-hom-tate-injective}
\dcref{M:ch4:IV.19}
\uses{mumford-prop-etale-coverings-av,mumford-thm-degree-polynomial}
For abelian varieties $X,Y$, $\operatorname{Hom}(X,Y)$ is a finitely
generated free abelian group, and for $l\ne\operatorname{char}k$,
\[
\mathbb Z_l\otimes_\mathbb Z\operatorname{Hom}(X,Y)\longrightarrow
\operatorname{Hom}_{\mathbb Z_l}(T_l(X),T_l(Y))
\]
is injective. In characteristic zero over $\mathbb C$, restriction to the
lattices in $X_i=V_i/U_i$ injects Hom into
$\operatorname{Hom}_{\mathbb Z}(U_1,U_2)$.
\source{mumford-abelian-varieties:page-0186}
\source{mumford-abelian-varieties:page-0187}
\source{mumford-abelian-varieties:page-0188}
\source{mumford-abelian-varieties:page-0189}
\end{theorem}
\begin{proof}
Complex homomorphisms lift to complex-linear maps $V_1\to V_2$ carrying
$U_1$ into $U_2$, so the lattice map is injective and gives the stated
finite rank bound. For arbitrary $k$, use $T_l$. For a finitely generated
subgroup $M$, Step I shows its saturation
$\mathbb QM\cap\operatorname{Hom}(X,Y)$ is finitely generated: reduce by
isogenies to simple factors and use the degree polynomial, whose nonzero
values are bounded away from zero on a lattice. For a saturated $M$ with
basis $f_i$, a nontrivial $l$-adic relation in the Tate representation can
be approximated by an integral relation $\sum n_if_i$ not all divisible by
$l$. Its Tate map is zero, so it factors through multiplication by $l$,
contradicting saturation. Thus the Tate map is injective. Finite generation
and torsion-freeness give freeness.
\end{proof}

\begin{corollary}[Neron--Severi and endomorphism algebras]
\label{mumford-cor-ns-finite-free}
\dcref{M:ch4:IV.19}
$\operatorname{NS}(X)=\operatorname{Pic}X/\operatorname{Pic}^0X$ is free of
finite rank, and $\operatorname{End}X$ is a finite-dimensional semisimple
algebra over $\mathbb Q$.
\source{mumford-abelian-varieties:page-0189}
\uses{mumford-thm-hom-tate-injective}
\end{corollary}
\begin{proof}
The map $L\mapsto\phi_L$ injects $\operatorname{NS}(X)$ into
$\operatorname{Hom}(X,\widehat X)$, so the first assertion follows. The
second follows from the simple decomposition and the division-ring assertion
for a simple factor.
\end{proof}

\begin{lemma}[Norms and traces of simple algebras]
\label{mumford-lem-reduced-norm-simple-algebra}
\dcref{M:ch4:IV.19}
\uses{mumford-cor-simple-decomposition}
For a finite-dimensional associative simple separable algebra $A$ over
$\Gamma$, with center $\Lambda$, there are canonical reduced norm and trace
forms. Every norm is
$(\operatorname{Nm}_{\Lambda/\Gamma}\circ N^0)^k$ and every trace is
$\phi\circ\operatorname{Tr}^0$; if $[A:\Lambda]=d^2$, $N^0$ has degree $d$.
\source{mumford-abelian-varieties:page-0189}
\source{mumford-abelian-varieties:page-0190}
\source{mumford-abelian-varieties:page-0191}
\end{lemma}
\begin{proof}
After a separable closure, $A$ becomes a product of matrix algebras, where
the assertion is determinant and trace. Writing the factors using the
embeddings $\sigma_i:\Lambda\to\overline\Gamma$, a norm is
$\prod_iN_i^0(\phi_i(\alpha))^{n_i}$. Galois transitivity forces all
$n_i$ equal, giving the displayed norm; the trace argument is analogous.
\end{proof}

\begin{theorem}[Degree and Tate determinant]
\label{mumford-thm-degree-tate-determinant}
\dcref{M:ch4:IV.19}
\uses{mumford-lem-reduced-norm-simple-algebra,mumford-thm-hom-tate-injective}
For $f\in\operatorname{End}X$ and $l\ne\operatorname{char}k$,
\[
\deg f=\det T_l(f).
\]
Thus $\deg(n_X-f)=P(n)$, where $P(t)=\det(t-T_l(f))$ is monic of degree
$2g$ with integral rational coefficients and $P(f)=0$.
\source{mumford-abelian-varieties:page-0191}
\source{mumford-abelian-varieties:page-0192}
\end{theorem}
\begin{proof}
Both sides extend to norm forms of degree $2g$ on
$\mathbb Q_l\otimes\operatorname{End}X$. Their $l$-adic absolute values
agree because the power of $l$ in $\deg f$ is the order of the kernel on
$X_{l^n}$, hence the order of the cokernel of $T_l(f)$. Decomposition into
simple factors and the preceding norm lemma give equality. The
characteristic-polynomial assertions follow.
\end{proof}

\begin{remark}[Characteristic and CM type]
\label{mumford-rem-endomorphism-characteristic}
\dcref{M:ch4:IV.19}
\uses{mumford-thm-degree-tate-determinant}
The constant term and negative coefficient of $t^{2g-1}$ in the polynomial
above are respectively the norm and trace. If $X$ is simple, with center
$K$, $[K:\mathbb Q]=e$, and $[\operatorname{End}^0X:K]=d^2$, then $de\mid2g$.
It is of CM type precisely when $de=2g$, equivalently when
$\operatorname{End}^0X$ contains a field of degree $2g$ over $\mathbb Q$.
\source{mumford-abelian-varieties:page-0193}
\source{mumford-abelian-varieties:page-0194}
\end{remark}

\section{Riemann forms}
\label{mumford-IV20-opening-source}
\dcref{M:ch4:IV.20}

\begin{definition}[Tate pairing]
\label{mumford-def-weil-pairing-ladic}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-etale-coverings-av}
For $l\ne\operatorname{char}k$, put
$M_l=\varprojlim\mu_{l^n}\simeq\mathbb Z_l$. For $n$ prime to the
characteristic, the kernels of $n_X$ and $n_{\widehat X}$ have a canonical
pairing $\bar e_n:X_n\times(\widehat X)_n\to\mu_n$.
\source{mumford-abelian-varieties:page-0194}
\end{definition}

\begin{lemma}[Divisor formula for the pairing]
\label{mumford-lem-riemann-pairing-divisor}
\dcref{M:ch4:IV.20}
\uses{mumford-def-weil-pairing-ladic}
If $(f)=nD$ and $(g)=n_X^{-1}(D)$, then
\[
\bar e_n(a,\lambda)=g(x)/g(x+a).
\]
\source{mumford-abelian-varieties:page-0195}
\end{lemma}
\begin{proof}
Since $L^n$ and $n_X^*L$ are trivial, choose $f,g$ as stated. Then
$n_X^*f=(g^n)$, so $g^n(x)=\alpha f(nx)$; hence the ratio is a constant
$n$th root of unity, equal to the pairing.
\end{proof}

\begin{proposition}[Compatibility of pairings]
\label{mumford-prop-riemann-pairing-compatibility}
\dcref{M:ch4:IV.20}
\uses{mumford-lem-riemann-pairing-divisor}
For coprime $m,n$, $x\in X_{mn}$ and $y\in(\widehat X)_{mn}$,
\[
\bar e_n(mx,my)=\bar e_{mn}(x,y)^m.
\]
\source{mumford-abelian-varieties:page-0196}
\end{proposition}
\begin{proof}
For a complete variety with a free action of a finite group $G$, and a
normal subgroup $H$, a line bundle on the quotient by $G$ which becomes
trivial on the quotient by $H$ has its $G/H$ character pulled back to a
$G$-character. Apply this with $G=X_{mn}$ and $H=X_m$; the quotient maps
are multiplication maps, giving the formula.
\end{proof}




\section{Riemann forms}
\label{mumford-IV20-source}
\dcref{M:ch4:IV.20}

\begin{proposition}[Tate pairing and Riemann form]
\label{mumford-prop-tate-riemann-pairing}
\dcref{M:ch4:IV.20}
\uses{mumford-def-weil-pairing-ladic}
There is a natural non-degenerate $\mathbb Z_l$-bilinear pairing
\[
e_l:T_l(X)\times T_l(\widehat X)\longrightarrow M_l.
\]
If $f:X\to Y$ has dual $\widehat f$, then
\[
e_l(T_l(f)\xi,\eta)=e_l(\xi,T_l(\widehat f)\eta).
\]
For a line bundle $L$ on $X$, define
\[
E^L(x,y)=e_l(x,T_l(\phi_L)(y)).
\]
\source{mumford-abelian-varieties:page-0197}
\end{proposition}

\begin{theorem}[Skew-symmetry of the Riemann form]
\label{mumford-thm-riemann-form-skew}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-tate-riemann-pairing}
The form $E^L$ is skew-symmetric for every line bundle $L$.
Consequently $L\mapsto E^L$ injects
\[
\operatorname{NS}(X)\longrightarrow
\{\text{alternating forms }T_l(X)\times T_l(X)\to M_l\}.
\]
\source{mumford-abelian-varieties:page-0197}
\source{mumford-abelian-varieties:page-0198}
\end{theorem}
\begin{proof}
It suffices to show $e_l(a,\phi_L(a))=1$ for $a\in X_l$. If $a\in X_n$
and $(g)=n_X^{-1}(T_aD-D)$ for a divisor $D$ representing $L$, choose
$b$ with $nb=a$. Then $h(x)=\prod_{i=0}^{n-1}g(x+ib)$ is constant, and
\[
1=\frac{h(x+b)}{h(x)}=\frac{g(x+a)}{g(x)}.
\]
Thus the pairing is trivial on the diagonal. If $E^L=0$, then
$T_l(\phi_L)=0$, and faithfulness of the Tate representation gives
$\phi_L=0$, proving injectivity modulo $\operatorname{Pic}^0$.
\end{proof}

\begin{proposition}[Pullback of Riemann forms]
\label{mumford-prop-riemann-form-pullback}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-tate-riemann-pairing}
For a homomorphism $f:X\to Y$ and a line bundle $L$ on $Y$,
\[
E^{f^*L}(x,y)=E^L(T_l(f)x,T_l(f)y).
\]
\source{mumford-abelian-varieties:page-0198}
\end{proposition}
\begin{proof}
Using $\phi_{f^*L}=\widehat f\phi_Lf$ and adjointness,
\[
\begin{aligned}
E^{f^*L}(x,y)&=e_l(x,\phi_{f^*L}(y))\\
&=e_l(x,T_l(\widehat f\phi_Lf)(y))
=e_l(T_l(f)x,\phi_L(T_l(f)y)).
\end{aligned}
\]
\end{proof}

\begin{proposition}[The Poincare Riemann form]
\label{mumford-prop-poincare-riemann-form}
\dcref{M:ch4:IV.20}
\uses{mumford-thm-riemann-form-skew,mumford-thm-poincare-universal-mapping}
Under $T_l(X\times\widehat X)=T_l(X)\times T_l(\widehat X)$,
\[
E^P((x,\widehat x),(y,\widehat y))
=e_l(x,\widehat y)-e_l(y,\widehat x).
\]
\source{mumford-abelian-varieties:page-0198}
\source{mumford-abelian-varieties:page-0199}
\end{proposition}
\begin{proof}
By skew-symmetry and linearity it suffices to consider the two factors
separately. The first two restrictions of $P$ are trivial. The canonical
identification $\widehat{X\times Y}\simeq\widehat X\times\widehat Y$ gives
$\phi_P(x,\widehat x)=(\widehat x,\phi(x))$, and hence the cross term is
$e_l(x,\widehat y)$; skew-symmetry supplies the other cross term.
\end{proof}

\begin{theorem}[Skew forms and line bundles]
\label{mumford-thm-riemann-form-line-bundle}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-poincare-riemann-form}
For a homomorphism $\phi:X\to\widehat X$, the form
$e_l(x,\phi(y))$ is skew-symmetric if and only if there is a line bundle
$L$ with $2\phi=\phi_L$.
\source{mumford-abelian-varieties:page-0199}
\end{theorem}
\begin{proof}
The forward implication follows from Theorem 1. Conversely, pull back $P$
along $(1,\phi):X\to X\times\widehat X$ to obtain $L$. Then
\[
e_l(x,\phi_L(y))=E^P((x,\phi x),(y,\phi y))
=e_l(x,\phi y)-e_l(y,\phi x)=2e_l(x,\phi y),
\]
so faithfulness gives $2\phi=\phi_L$.
\end{proof}

\begin{proposition}[Rosati involution]
\label{mumford-prop-rosati-involution}
\dcref{M:ch4:IV.20}
\uses{mumford-prop-tate-riemann-pairing}
For ample $L$ on $X$, define
\[
\phi'=\phi_L^{-1}\widehat\phi\phi_L.
\]
Then $'$ is a $\mathbb Q$-linear involution,
$(\phi\psi)'=\psi'\phi'$, and
\[
E^L(\phi x,y)=E^L(x,\phi'y).
\]
\source{mumford-abelian-varieties:page-0200}
\end{proposition}
\begin{proof}
Extend $T_l$ to $\operatorname{End}^0X$. The displayed identity follows
from the Tate adjunction:
\[
E^L(x,\phi'y)=e_l(x,\widehat\phi\phi_L(y))
=e_l(\phi x,\phi_L(y))=E^L(\phi x,y).
\]
Non-degeneracy gives all involution identities.
\end{proof}

\begin{theorem}[Neron--Severi classes and Rosati fixed points]
\label{mumford-thm-ns-rosati-fixed}
\dcref{M:ch4:IV.20}
\uses{mumford-thm-riemann-form-line-bundle,mumford-prop-rosati-involution}
Under $\operatorname{Hom}^0(X,\widehat X)\simeq\operatorname{End}^0X$ via
$\psi\mapsto\phi_L^{-1}\psi$, the space
$\mathbb Q\otimes\operatorname{NS}(X)$ is exactly the fixed subspace of
the Rosati involution.
\source{mumford-abelian-varieties:page-0201}
\end{theorem}
\begin{proof}
By the preceding skew-form theorem, $\psi$ comes from a divisor precisely
when $e_l(x,\psi y)=-e_l(y,\psi x)$. This is equivalent to
\[
E^L(x,\psi y)=E^L(\psi x,y)=E^L(x,\psi'y).
\]
Non-degeneracy and faithfulness give $\psi=\psi'$.
\end{proof}

\begin{theorem}[Wedge and intersection numbers]
\label{mumford-thm-riemann-wedge-intersection}
\dcref{M:ch4:IV.20}
\uses{mumford-thm-riemann-roch,mumford-thm-degree-tate-determinant}
There is a generator
$v\in\operatorname{Hom}_{\mathbb Z_l}(\Lambda^2T_l(X),M_l)$ such that
for divisors $D_i$ and $E_i=E^{\mathcal O_X(D_i)}$,
\[
E_1\wedge\cdots\wedge E_g=(D_1\cdots D_g)v.
\]
\source{mumford-abelian-varieties:page-0201}
\source{mumford-abelian-varieties:page-0202}
\end{theorem}
\begin{proof}
Both sides are polynomial in the Neron--Severi classes, so polarization
reduces to one bundle $L$. Riemann--Roch gives
$[E^L]^{\wedge g}=g!\chi(L)v$. In a basis,
\[
([E^L]^{\wedge g})^2=(\det E^L)(g!)^2.
\]
Since $\det E^L=\det T_l(\phi_L)$ and the degree/determinant comparison
differs only by an $l$-adic unit, the normalization of $v$ gives the result.
\end{proof}

\begin{corollary}[Degree of a fixed subalgebra]
\label{mumford-cor-rosati-subalgebra-degree}
\dcref{M:ch4:IV.20}
\uses{mumford-thm-riemann-wedge-intersection}
If $X$ is simple and $K\subset\operatorname{End}^0X$ is a $\mathbb Q$-subalgebra
fixed by Rosati, then $[K:\mathbb Q]$ divides $\dim X$.
\source{mumford-abelian-varieties:page-0202}
\source{mumford-abelian-varieties:page-0203}
\end{corollary}
\begin{proof}
The ratio $\chi(M)/\chi(L)$ is a norm form on $K$ of degree $g$, since its
square is $\deg(\phi_L^{-1}\phi_M)$. The degree of a field therefore divides
the degree of this norm form.
\end{proof}

\section{Positivity of the Rosati involution}
\label{mumford-IV21-source}
\dcref{M:ch4:IV.21}

\begin{theorem}[Positive Rosati trace]
\label{mumford-thm-rosati-positive}
\dcref{M:ch4:IV.21}
\uses{mumford-thm-riemann-wedge-intersection,mumford-prop-rosati-involution}
For an ample divisor $H$, $L=\mathcal O_X(H)$, and the Rosati involution
defined by $L$,
\[
\operatorname{Tr}(\phi\phi')
=\frac{2g}{(H^g)}(H^{g-1}\cdot\phi^*H),
\]
and $\phi\mapsto\operatorname{Tr}(\phi\phi')$ is positive definite.
\source{mumford-abelian-varieties:page-0203}
\source{mumford-abelian-varieties:page-0204}
\end{theorem}
\begin{proof}
The wedge/intersection theorem gives
\[
\frac{(E^L)^{\wedge(2g-1)}\wedge E^{\phi^*L}}
     {(E^L)^{\wedge2g}}
=\frac{(H^{g-1}\cdot\phi^*H)}{(H^g)}
=\frac1{2g}\operatorname{Tr}(\phi\phi').
\]
Choose a symplectic basis for $E^L$ and expand exterior multiplication. The
resulting quadratic form is a sum of squares, hence positive definite.
\end{proof}

\begin{proposition}[Simple endomorphism algebras: initial classification]
\label{mumford-prop-simple-endomorphism-classification}
\dcref{M:ch4:IV.21}
\uses{mumford-thm-rosati-positive,mumford-cor-simple-decomposition}
For simple $X$, $D=\operatorname{End}^0X$ is a division algebra with a
positive involution. If $K$ is its center, $K_0=\{x\in K:x'=x\}$,
$[D:K]=d^2$, and $[K:\mathbb Q]=e$, then $K_0$ is totally real. If
$K\ne K_0$, it is totally imaginary over $K_0$ and the involution is of the
second kind; otherwise it is of the first kind. In the nontrivial Brauer
class case of the first kind, $D$ is a quaternion division algebra.
\source{mumford-abelian-varieties:page-0204}
\source{mumford-abelian-varieties:page-0205}
\source{mumford-abelian-varieties:page-0206}
\end{proposition}
\begin{proof}
Write the real algebra of $K_0$ as
$\mathbb R^{r_1}\times\mathbb C^{r_2}$. Positivity of
$\operatorname{Tr}(xx')$ rules out complex embeddings, so $K_0$ is totally
real. If $K\ne K_0$, positivity forces the quadratic extension to be
totally imaginary. For an involution of the first kind, $D$ is identified
with its opposite algebra, so its Brauer class has order one or two. In the
order-two case its rank over $K$ is four. The canonical quaternion
involution is $x^*=\operatorname{Tr}^0_{D/K}x-x$; Skolem--Noether gives
$x'=ax^*a^{-1}$ with $a^*=\epsilon a$. Extending to the real factors,
positivity excludes $M_2(\mathbb R)$ and leaves Hamilton quaternion factors
with the corresponding positive involutions.
\end{proof}




\section{Classification of positive involutions}
\label{mumford-IV21-classification-source}
\dcref{M:ch4:IV.21}

\begin{theorem}[Brauer groups and positive involutions]
\label{mumford-thm-positive-involution-classification}
For a division algebra $D$ with positive involution, the involution is one of
the Albert types: (I) a totally real field with identity involution; (II)
a quaternion division algebra over a totally real field with an orthogonal
involution; (III) a quaternion division algebra with its canonical
involution; or (IV) an algebra with totally imaginary quadratic center over
a totally real fixed field, with conjugation on the complex factors.
\source{mumford-abelian-varieties:page-0207}
\source{mumford-abelian-varieties:page-0208}
\source{mumford-abelian-varieties:page-0209}
\source{mumford-abelian-varieties:page-0210}
\source{mumford-abelian-varieties:page-0211}
\source{mumford-abelian-varieties:page-0212}
\source{mumford-abelian-varieties:page-0213}
\end{theorem}
\begin{proof}
For an involution of the second kind, class field theory gives
\[
0\to\operatorname{Br}(K)\to\prod_v\operatorname{Br}(K_v)
\to\mathbb Q/\mathbb Z\to0,
\]
with $\operatorname{Br}(\mathbb R)$ of order two and
$\operatorname{Br}(\mathbb C)=0$. If $\sigma$ is the involution on the
center, local invariants satisfy
$\operatorname{Inv}_v(D)+\operatorname{Inv}_{\sigma v}(D)=0$.
Skolem--Noether writes $x'=ax^*a^{-1}$, and the norm condition
$a^*a\in N_{K/K_0}K^*$ is equivalent to the existence of the involution.
For a first-kind involution, the Brauer class has order one or two; the
nontrivial case is quaternionic. Extending to the real factors, positivity
rules out $M_2(\mathbb R)$ in the canonical case and leaves Hamilton factors.
For complex factors the involution is $(X_i)\mapsto
A_i\overline{X_i}A_i^{-1}$; positivity makes $A_i$ positive definite,
and an inner change reduces to standard conjugation. These calculations give
the four listed types.
\end{proof}

\begin{proposition}[Albert numerical table]
\label{mumford-prop-albert-invariants}
For $S=\{x\in D:x'=x\}$, $\eta=\dim_{\mathbb Q}S/\dim_{\mathbb Q}D$,
and $[D:K]=d^2$, $[K_0:\mathbb Q]=e_0$, the four types have
\[
\begin{array}{c|c|c|c}
\text{type}&e&d&\eta\\ \hline
I&e_0&1&1\\ II&e_0&2&1/2\\ III&e_0&2&1/2\\ IV&2e_0&d&1/2.
\end{array}
\]
For endomorphism algebras of simple abelian varieties these invariants obey
the divisibility restrictions by $g=\dim X$.
\source{mumford-abelian-varieties:page-0212}
\source{mumford-abelian-varieties:page-0213}

\notready
\end{proposition}

\section{The Riemann hypothesis}
\label{mumford-IV-rh-source}
\dcref{M:ch4:IV.21}

\begin{proposition}[Characteristic roots]
\label{mumford-prop-characteristic-root-modulus}
If $\alpha'\alpha=a\in\mathbb Z$ and $\omega_i$ are the roots of the
characteristic polynomial of $\alpha$, then $\mathbb Q[\alpha]$ is
semisimple, $|\omega_i|^2=a$, and $\omega_i\mapsto a/\omega_i$ permutes
the roots.
\source{mumford-abelian-varieties:page-0214}
\source{mumford-abelian-varieties:page-0215}
\end{proposition}
\begin{proof}
The minimal polynomial divides the characteristic polynomial and has the
same roots. The trace restricted to $\mathbb Q[\alpha]$ is positive; an
ideal and its trace-orthogonal complement split the algebra, proving
semisimplicity. Its simple factors are totally real fields or totally
imaginary quadratic extensions. The involution sends each root to its
complex conjugate, while $\alpha'\alpha=a$, hence
$a=\omega_i\overline{\omega_i}=|\omega_i|^2$.
\end{proof}

\begin{theorem}[Lang and Weil]
\label{mumford-thm-lang-frobenius-rh}
If $X_0$ is a scheme over $\mathbb F_q$ whose base change $X$ is an abelian
variety, then $X_0(\mathbb F_q)\ne\varnothing$. If $\pi$ is Frobenius and
$\omega_i$ are its characteristic roots, then
\[
\#X(\mathbb F_{q^n})=\prod_i(1-\omega_i^n),
\qquad |\omega_i|=\sqrt q,
\qquad \omega_{\pi(i)}=q/\omega_i.
\]
\source{mumford-abelian-varieties:page-0215}
\source{mumford-abelian-varieties:page-0216}
\source{mumford-abelian-varieties:page-0217}
\end{theorem}
\begin{proof}
Frobenius is the identity on the underlying space, is functorial, and has
zero differential. Write it as $\pi(x)=x_0+f(x)$. Then $1-f$ has identity
differential, hence zero-dimensional kernel and is surjective. Choose
$x_1$ with $(1-f)x_1=x_0$; then $x_1=\pi(x_1)$.
Thus $\#X(\mathbb F_{q^n})=\deg(1-\pi^n)$. After replacing the field,
choose an ample bundle; Rosati gives $\pi'\pi=q$, yielding the reciprocal
root relation and $|\omega_i|=\sqrt q$.
\end{proof}

\begin{corollary}[Weil estimate]
\label{mumford-cor-weil-point-count-estimate}
For some constant $C$,
$|\#X(\mathbb F_{q^n})-q^{ng}|\le Cq^{n(g-1/2)}$.
\source{mumford-abelian-varieties:page-0218}
\uses{mumford-thm-lang-frobenius-rh}
\end{corollary}

\begin{theorem}[Serre torsion restriction]
\label{mumford-thm-serre-torsion-restriction}
For $n\ge3$ and ample $L$, the restriction from automorphisms preserving
$L$ modulo $\operatorname{Pic}^0X$ to $\operatorname{Aut}(X_n)$ is injective.
\source{mumford-abelian-varieties:page-0218}
\end{theorem}
\begin{proof}
The characteristic roots are algebraic integers all of whose conjugates
have absolute value one, hence roots of unity. If $\alpha$ is the identity
on $X_n$, write $\alpha-1=n\beta$; the root-of-unity lemma forces
$\alpha=1$ for $n>3$.
\end{proof}

\section{The Jordan algebra of $NS^0(X)$}
\label{mumford-IV21-jordan-source}
\dcref{M:ch4:IV.21}

\begin{proposition}[Real structure of $NS^0$]
\label{mumford-prop-ns-jordan-structure}
For an ample $L$,
\[
NS^0(X)\simeq\{\alpha\in\operatorname{End}^0X:\alpha'=\alpha\}.
\]
With product $\alpha\circ\beta=(\alpha\beta+\beta\alpha)/2$, this is a
formally real Jordan algebra, a product over $\mathbb R$ of real symmetric,
complex Hermitian, and quaternionic Hermitian matrix algebras. Ample bundles
are exactly its totally positive elements.
\source{mumford-abelian-varieties:page-0219}
\source{mumford-abelian-varieties:page-0220}
\source{mumford-abelian-varieties:page-0221}
\uses{mumford-thm-ns-rosati-fixed,mumford-thm-rosati-positive}

\notready
\end{proposition}

\section{Complex multiplication and finite fields}
\label{mumford-IV22-source}
\dcref{M:ch4:IV.22}

\begin{theorem}[CM complex-torus classification]
\label{mumford-thm-cm-complex-classification}
Let $K_0$ be totally real of degree $g$ and $K$ a totally imaginary quadratic
extension. The pairs $(X,i)$ with $X/\mathbb C$ an abelian variety and
$i:K\hookrightarrow\operatorname{End}^0X$ have exactly $2^g$ isomorphism
classes up to isogeny. Representatives are
$X(K,\Phi)=(\mathbb R\otimes_{\mathbb Q}K)/A_0$, one for each of the
$2^g$ complex-algebra structures $\Phi$ on $\mathbb R\otimes K$.
\source{mumford-abelian-varieties:page-0221}
\source{mumford-abelian-varieties:page-0222}
\source{mumford-abelian-varieties:page-0223}
\source{mumford-abelian-varieties:page-0224}
\end{theorem}
\begin{proof}
The lattice $U$ is a finite-index $A_0$-module; after isogeny it is $A_0$.
The $K$-action pulls the complex structure back to a $\mathbb C$-algebra
structure $\Phi$. There are two embeddings over each real embedding of
$K_0$, hence $2^g$ structures. Choose $\alpha\in K$ with
$\alpha^2\in K_0$ and embeddings $\tau_i(\alpha)=i\beta_i$, $\beta_i>0$.
Then
\[
H(x,y)=2\sum_i\beta_i\tau_i(x)\overline{\tau_i(y)}
\]
is positive definite, and for $x,y\in A_0$,
\[
\operatorname{Im}H(x,y)=-\operatorname{Tr}_{K/\mathbb Q}(\alpha xy)\in\mathbb Z.
\]
Thus the torus is an abelian variety. An equivalence preserving the $K$-
action is $K$-linear and, after normalization, the identity; so distinct
$\Phi$ are inequivalent.
\end{proof}

\begin{theorem}[Deuring]
\label{mumford-thm-deuring-elliptic}
For an elliptic curve in characteristic $p$, non-finite-field definition is
equivalent to $\operatorname{End}^0X=\mathbb Q$. If $X$ is defined over a
finite field, its endomorphism algebra is imaginary quadratic exactly when
the $p$-rank is one; for $p$-rank zero it is the quaternion division algebra
with local invariants $\operatorname{Inv}_p=\operatorname{Inv}_\infty=1/2$
and all other finite invariants zero.
\source{mumford-abelian-varieties:page-0228}
\source{mumford-abelian-varieties:page-0229}
\source{mumford-abelian-varieties:page-0230}
\source{mumford-abelian-varieties:page-0231}
\end{theorem}
\begin{proof}
Let (A) be $p$-rank zero, (B) noncommutative endomorphism algebra, and (C)
finite-field definition with $\pi^n=p_X^m$. The classification table and
the $p$-adic Tate representation give (B)$\Rightarrow$(A). If (A) and the
algebra is commutative, cyclic Tate subgroups and quotients yield an
endomorphism with cyclic $l$-power kernel, contradicting the norm in a
number field; hence (A)$\Rightarrow$(B). Frobenius centrality gives
(A)$\Leftrightarrow$(C), and the local invariants follow from the sum of
invariants. In the non-finite-field case, a quadratic endomorphism acting
scalarly on a Tate module would have rational scalar with negative square,
impossible; hence the algebra is $\mathbb Q$.
\end{proof}

\begin{theorem}[CM over finite fields]
\label{mumford-thm-cm-finite-field-isogeny}
A simple abelian variety in characteristic $p$ is isogenous to one defined
over a finite field if and only if it is of CM type.
\source{mumford-abelian-varieties:page-0231}

\notready
\end{theorem}

\begin{theorem}[Tate centralizer theorem]
\label{mumford-thm-tate-centralizer}
If $X$ is defined over a finite field $k_0$, with Frobenius $\pi$, then
\[
\operatorname{End}(X,k_0)\otimes\mathbb Q_l
=\operatorname{Cent}_{\operatorname{End}_{\mathbb Q_l}(T_lX)}(T_l\pi).
\]
\source{mumford-abelian-varieties:page-0232}

\notready
\end{theorem}

\section{The theta group of a line bundle}
\label{mumford-IV23-source}
\dcref{M:ch4:IV.23}

\begin{definition}[Theta group]
\label{mumford-def-theta-group}
A theta-group is an exact sequence
\[
1\to\mathbb G_m\xrightarrow{i}G\xrightarrow{\pi}K\to1
\]
where $K$ is commutative, the sequence is locally split, $i$ is a closed
immersion identifying the kernel, and $\mathbb G_m$ is central. For finite
$K$, a section identifies the underlying scheme with
$\mathbb G_m\times K$ and the group law with
\[
(\alpha,k)(\alpha',k')=(\alpha\alpha'f(k,k'),k+k'),
\]
where $f$ is a 2-cocycle, defined up to coboundary.
\source{mumford-abelian-varieties:page-0232}
\source{mumford-abelian-varieties:page-0233}
\end{definition}

\begin{proposition}[Theta commutator]
\label{mumford-prop-theta-commutator}
The commutator defines a skew-symmetric bihomomorphism
$e:K\times K\to\mathbb G_m$, and hence a homomorphism
$\gamma:K\to\widehat K$ with
$e(k,k')=\langle k,\gamma(k')\rangle$. The center of $G$ maps to
$\ker\gamma$; if $K$ is finite, the center is exactly $\mathbb G_m$ iff
$\gamma$ is an isomorphism.
\source{mumford-abelian-varieties:page-0233}
\source{mumford-abelian-varieties:page-0234}
\end{proposition}
\begin{proof}
The commutator is independent of lifts because $\mathbb G_m$ is central.
The group identities give bihomomorphy and skew-symmetry. Viewing
$(e,p_2):K\times K\to\mathbb G_m\times K$ over $K$ gives $\gamma$.
The displayed universal pairing shows that $\gamma(\pi(x))$ is trivial
exactly when $x$ commutes with every base change of every point of $G$.
\end{proof}

\begin{lemma}[Trivial theta extensions]
\label{mumford-lem-theta-extension-prime-order}
If $K$ is finite and $G$ commutative, then
$G\simeq\mathbb G_m\times K$ as a group. If $K$ has prime order, then $G$
is commutative.
\source{mumford-abelian-varieties:page-0235}
\end{lemma}
\begin{proof}
The first assertion reduces by an Ext sequence to cyclic prime-order,
$\mu_p$, and $\alpha_p$ cases; divisibility of $k^*$ splits the reduced
cases and the height-one Lie algebra calculation splits the latter cases.
For prime order, reduced cases are generated by a central subgroup and one
lift. In the infinitesimal cases the Lie algebra is abelian, so the
height-one subgroup is commutative; together with the central torus this
makes $G$ commutative.
\end{proof}

\begin{theorem}[Theta group of a line bundle]
\label{mumford-thm-line-bundle-theta-group}
For a line bundle $L$ on an abelian variety $X$, the functor of automorphisms
of $S\times L$ covering translations of $S\times X$ is represented by a
group scheme $\mathcal G(L)$, fitting into a theta-group extension
\[
1\to\mathbb G_m\to\mathcal G(L)\to K(L)\to1.
\]
\source{mumford-abelian-varieties:page-0235}
\source{mumford-abelian-varieties:page-0236}
\uses{mumford-def-theta-group}
\end{theorem}
\begin{proof}
Let $L^*$ be the complement of the zero section. Fix $P_0$ over the origin
and set $\mathcal G(L)=p^{-1}(K(L))\cap L^*$. An automorphism over a
translation $T_f$ sends $P_0$ to a morphism $S\to L^*$ over $f$, hence
factors through $\mathcal G(L)$. This gives the representing map; its
inverse is obtained by translating the fibre and using linearity. Scalar
automorphisms form $\mathbb G_m$, and the quotient is $K(L)$.
\end{proof}




\section{Theta groups and descent}
\label{mumford-IV23-continuation-source}
\dcref{M:ch4:IV.23}

\begin{proof}[Continuation of the theta-group theorem]
\label{mumford-proof-line-bundle-theta-group-continuation}
If two automorphisms of $S\times L$ covering the same translation have the
same image in $\mathcal G(L)$, their quotient is multiplication by a unit on
$S\times X$ restricting to $1$ over the chosen point. Since
$H^0(S\times X,\mathcal O^*)=H^0(S,\mathcal O_S^*)$, it is the identity.
Conversely, a point $\phi\in\mathcal G(L)(S)$ covers $f\in K(L)(S)$.
Locally on $S$, trivialize the line bundle $M$ in
$T_f^*(S\times L)\simeq(S\times L)\otimes p_1^*M$ and choose liftings
$\chi_i$ of the translations. Since $\mathcal G(L)$ is a principal
$\mathbb G_m$-bundle over $K(L)$, rescale $\chi_i$ by units so their images
are $\phi$. Injectivity makes the rescaled liftings agree on overlaps, hence
they glue. Therefore
$\underline{\operatorname{Aut}}(L/X)\simeq\mathcal G(L)$.
\source{mumford-abelian-varieties:page-0237}
\source{mumford-abelian-varieties:page-0238}
\end{proof}

\begin{definition}[Commutator pairing of a line bundle]
\label{mumford-def-line-bundle-commutator}
The theta group $\mathcal G(L)$ has a skew-symmetric bihomomorphism
\[
e^L:K(L)\times K(L)\to\mathbb G_m
\]
defined by its commutator. If $L\in\operatorname{Pic}^0X$, then $K(L)=X$,
so $e^L=1$ and $\mathcal G(L)$ is commutative.
\source{mumford-abelian-varieties:page-0238}
\end{definition}

\begin{proposition}[Functoriality of commutator pairings]
\label{mumford-prop-line-bundle-commutator-functorial}
For homomorphisms and line bundles as indicated,
\begin{enumerate}
\item $e^{f^*L}(x,y)=e^L(fx,fy)$;
\item $e^{L_1\otimes L_2}(x,y)=e^{L_1}(x,y)e^{L_2}(x,y)$;
\item algebraically equivalent line bundles have equal pairings;
\item $e^{L^n}(x,y)=e^L(x,ny)$ for $x\in K(L)$,
$y\in n_X^{-1}K(L)$;
\item if $x\in X_n$ and $y\in\phi_L^{-1}(X_n)$, then
$\bar e_n(x,\phi_L(y))=e^{L^n}(x,y)$.
\end{enumerate}
\source{mumford-abelian-varieties:page-0239}
\source{mumford-abelian-varieties:page-0240}
\source{mumford-abelian-varieties:page-0241}
\end{proposition}
\begin{proof}
Lift $f(x),f(y)$ to automorphisms in the theta group; their commutator
proves (1). Tensoring liftings proves (2), and (3) follows by writing
$L_1=L_2\otimes L_3$ with $L_3\in\operatorname{Pic}^0X$. For (4), after a
faithfully flat extension write $x=nz$; then
\[
e^L(nz,ny)=e^{n_X^*L}(z,y)=e^{L^{n^2}}(z,y)
=(e^{L^n}(z,y))^n=e^{L^n}(nz,y).
\]
For (5), write $y=nz$ and compare
$n_X^*(T_y^*L\otimes L^{-1})$ with
the line bundle $\operatorname{Hom}[n_X^*L,T_{ny}^*n_X^*L]$. The action of $x\in X_n$ on
the resulting nowhere-vanishing section is conjugation by the natural
translation isomorphism; this is simultaneously the Weil pairing and the
theta-group commutator.
\end{proof}

\begin{theorem}[Descent of line bundles]
\label{mumford-thm-theta-descent}
For an isogeny $\pi:X\to Y$ and a line bundle $L$ on $X$, line bundles $M$
on $Y$ with $\pi^*M\simeq L$ correspond naturally to homomorphisms
$\alpha:\ker\pi\to\mathcal G(L)$ lifting the inclusion into $X$.
Such an $M$ exists iff $\ker\pi\subset K(L)$ and
$e^L$ is trivial on $\ker\pi\times\ker\pi$.
\source{mumford-abelian-varieties:page-0242}
\uses{mumford-def-line-bundle-commutator}
\end{theorem}
\begin{proof}
This is the finite-group-scheme descent theorem applied to the action of
$\ker\pi$ on $L$. The lift is a splitting of the inverse image theta group.
That theta group splits iff it is commutative, equivalently iff the
commutator pairing is trivial.
\end{proof}

\begin{theorem}[Power criterion]
\label{mumford-thm-line-bundle-power-criterion}
For a line bundle $L$ and integer $n$, $L\simeq M^n$ for some $M$ iff
$K(L)\supset X_n$.
\source{mumford-abelian-varieties:page-0242}
\source{mumford-abelian-varieties:page-0243}
\end{theorem}
\begin{proof}
The forward implication follows from $\phi_{M^n}=n\phi_M$. Conversely,
$K(L)\supset X_n$ gives
$e^{L^n}(x,y)=e^L(x,ny)=1$ for $x,y\in X_n$. The descent criterion gives
$L^n\simeq n_X^*N$; then $(L\otimes N^{-n})^n\in\operatorname{Pic}^0X$.
Divisibility of $\operatorname{Pic}^0X$ supplies $P$ with
$L\otimes N^{-n}\simeq P^n$, hence $L\simeq(N\otimes P)^n$.
\end{proof}

\begin{lemma}[Orthogonal subgroup]
\label{mumford-lem-theta-orthogonal-subgroup}
For a skew bihomomorphism $e:K\times K\to\mathbb G_m$ and subgroup $H$,
$H^\perp$ is the kernel of $K\xrightarrow\gamma\widehat K\to\widehat H$;
equivalently it consists of points pairing trivially with every base change of
every point of $H$. If $L=\pi^*M$ and $H=\ker\pi$, then
$K(M)\simeq H^\perp/H$.
\source{mumford-abelian-varieties:page-0243}
\source{mumford-abelian-varieties:page-0244}
\end{lemma}
\begin{proof}
The kernel description is immediate from restriction of characters. Locally
on a base $S$, descent identifies $\pi x\in K(M)$ with an isomorphism of
$T_x^*L$ with $L$ commuting with the $H$-action. A lift $w$ of $x$ in
$\mathcal G(L)$ commutes with that action exactly when
$e^L(x,h)=1$ for all $h\in H$, which is $x\in H^\perp$.
\end{proof}

\begin{theorem}[Maximal isotropic subgroup]
\label{mumford-thm-maximal-isotropic-theta}
If $L$ is non-degenerate and $H\subset K(L)$ is maximal with
$e^L|_{H\times H}=1$, then $H=H^\perp$ and
\[
\operatorname{order}(H)^2=\operatorname{order}(K(L)).
\]
\source{mumford-abelian-varieties:page-0244}
\source{mumford-abelian-varieties:page-0245}
\end{theorem}
\begin{proof}
Put $Y=X/H$ and $L=\pi^*M$. Maximality means $M$ admits no nontrivial
further descent. If a non-degenerate bundle admits no descent of degree
$>1$, then $|\chi(M)|=1$: otherwise a prime-order subgroup of $K(M)$,
whose theta extension is commutative, would give a descent. Hence
$K(M)=0$ and $|\chi(M)|=1$. The orthogonal lemma gives $H=H^\perp$; and
Riemann--Roch gives
$|\chi(L)|=\operatorname{order}(H)$ and
$\chi(L)^2=\operatorname{order}(K(L))$.
\end{proof}

\begin{corollary}[Principal polarization and non-degeneracy]
\label{mumford-cor-principal-polarization-theta}
Every abelian variety is isogenous to a principally polarized one. If $L$ is
non-degenerate, then $\mathcal G(L)$ is a non-degenerate theta group.
\source{mumford-abelian-varieties:page-0245}
\source{mumford-abelian-varieties:page-0246}
\uses{mumford-thm-maximal-isotropic-theta}
\end{corollary}
\begin{proof}
Apply the theorem to an ample $L$ and descend to $X/H$; the descended bundle
has Euler characteristic one. For the second assertion, let $D$ be the
kernel of the commutator map $\gamma$. If $H=H^\perp$, then $D\subset H$ and
the image of $K(L)$ in $\widehat H$ has kernel $D$. Therefore
\[
\operatorname{order}K(L)\leq\operatorname{order}H\cdot
\operatorname{order}(\widehat H/D)=
\frac{\operatorname{order}(H)^2}{\operatorname{order}D}.
\]
Since $\operatorname{order}K(L)=\operatorname{order}(H)^2$, $D=1$.
\end{proof}




\section{Analytic comparison of theta groups and pairings}
\label{mumford-IV24-analytic-comparison-source}
\dcref{M:ch4:IV.24}

\begin{theorem}[Analytic theta-group comparison]
\label{mumford-thm-analytic-theta-commutator}
\dcref{M:ch4:IV.24}
Let $L=L(H,\alpha)$ be a line bundle on $X=V/U$, let $E={\rm Im}\,H$, and
let $\pi:V\to X$ be the natural map. For $u,v\in U^\perp$,
\[
 e^{-2\pi iE(u,v)}=e^L(\pi u,\pi v).
\]
\source{mumford-abelian-varieties:page-0247}
\source{mumford-abelian-varieties:page-0248}
\uses{mumford-def-line-bundle-commutator,mumford-lem-theta-orthogonal-subgroup}
\end{theorem}
\begin{proof}
The analytic extension has composition
\[
 \psi_{\sigma,w}\psi_{\tau,v}=\psi_{\rho,w+v},
 \qquad \rho=\sigma\tau e^{\pi H(v,w)},
\]
and hence
$1\to\mathbb C^*\to\widetilde{\mathcal G}\to V\to1$.
The datum $\alpha$ lifts $U$ by
$i(u)=\psi_{\sigma,u}$ with $\sigma=\alpha(u)e^{2\pi H(u,u)}$; thus
$L(H,\alpha)=(\mathbb C^*\times V)/i(U)$. Its commutator is
\[
 \psi_{\sigma,w}\psi_{\tau,v}\psi_{\sigma,w}^{-1}\psi_{\tau,v}^{-1}
 =\psi_{\widetilde e(v,w),0},
 \qquad \widetilde e(v,w)=e^{2\pi iE(v,w)}.
\]
Therefore $p^{-1}(U^\perp)$ is the centralizer of $i(U)$, and its elements
descend to automorphisms of $L(H,\alpha)$. Since
$K(L(H,\alpha))\simeq U^\perp/U$, the extensions
\[
1\to\mathbb C^*\to\widetilde{\mathcal G}_0/i(U)\to U^\perp/U\to1,
\qquad
1\to\mathbb C^*\to\mathcal G(L(H,\alpha))\to K(L(H,\alpha))\to1
\]
are isomorphic. Their commutators agree, giving the formula.
\end{proof}

\begin{proposition}[Analytic and l-adic Riemann pairings]
\label{mumford-prop-analytic-ladic-pairing}
\dcref{M:ch4:IV.24}
For $X=V/U$ and $\ell$, the canonical pairing $E^L$ on $T_\ell X$ is, up to
sign, the $\mathbb Z_\ell$-linear extension of $E:U\times U\to\mathbb Z$.
In particular, for the Poincare bundle on $Y\times\widehat Y$, the analytic
pairing of $U,\widehat U$ agrees up to sign with the canonical pairing of
$T_\ell Y,T_\ell\widehat Y$.
\source{mumford-abelian-varieties:page-0248}
\source{mumford-abelian-varieties:page-0249}
\uses{mumford-thm-analytic-theta-commutator}
\end{proposition}
\begin{proof}
Let $M_\ell=\varprojlim_n\mu_{\ell^n}$ with basis
$\zeta=(e^{2\pi i/\ell^n})_n$. If $\pi_\ell(u)$ is represented by
$u_n=\pi(u/\ell^n)$, then
\[
\begin{aligned}
 E^L(\pi_\ell u,\pi_\ell v)
 &=\bigl(e_{\ell^n}^L(u_n,v_n)\bigr)_n
 =\bigl(e^{L^{\ell^n}}(u_n,v_n)\bigr)_n\\
 &=\bigl(e^{-2\pi i\ell^nE(u/\ell^n,v/\ell^n)}\bigr)_n
 =\bigl((\zeta_{\ell^n})^{-E(u,v)}\bigr)_n
 =-E(u,v)\cdot\zeta.
\end{aligned}
\]
The Poincare-bundle assertion is the corresponding non-degenerate case.
\end{proof}

\begin{proposition}[Analytic interpretation and positivity of Rosati]
\label{mumford-prop-analytic-rosati-positivity}
\dcref{M:ch4:IV.24}
Analytically,
\[
{\rm End}^0(X)=\{T:V\to V\text{ complex-linear}:T(\mathbb Q\cdot U)\subset\mathbb Q\cdot U\},
\]
and the Rosati involution is the $H$-adjoint $T^*$ defined by
$H(T^*x,y)=H(x,Ty)$. It equals the algebraic Rosati involution and satisfies
\[
{\rm Tr}(T^*T)\ge0,\qquad T\ne0.
\]
\source{mumford-abelian-varieties:page-0249}
\source{mumford-abelian-varieties:page-0250}
\uses{mumford-prop-analytic-ladic-pairing}
\end{proposition}
\begin{proof}
If $x\in\mathbb Q\cdot U$ and $y\in\mathbb Q\cdot U$, then
$E(T^*x,y)=E(x,Ty)\in\mathbb Q$, so $T^*$ preserves $\mathbb Q\cdot U$.
For $T'$ algebraic Rosati and $x,y\in U$,
\[
\begin{aligned}
 E((T^*-T')x,y)&={\rm Im}\,H(T^*x,y)+E^L(T'\pi x,T\pi y)\\
 &={\rm Im}\,H(x,Ty)+E^L(\pi x,T\pi y)=0,
\end{aligned}
\]
so $T^*=T'$. The operator $T^*T$ is positive self-adjoint for the positive
Hermitian form $H$, so its complex trace is positive. Its trace on the rational
space is twice the complex trace, and its $\ell$-adic trace on
$T_\ell X\simeq U\otimes\mathbb Z_\ell$ is the same rational trace. Hence
positivity follows.
\end{proof}


\appendix

\label{chap:mumford-mordell-weil}


\section{Mordell--Weil theorem}
\label{mumford-appendix-II-source}\dcref{M:appII:II}

\begin{theorem}[Mordell--Weil]\label{mumford-thm-mordell-weil}
Let $K$ be a finite extension of $\mathbb Q$ and $X$ an abelian variety over
$K$. Then $X(K)$ is finitely generated.
\source{mumford-abelian-varieties:page-0272}\uses{mumford-prop-weak-mordell-weil,mumford-prop-height-quadratic,mumford-prop-formal-finite-generation}
\end{theorem}
\begin{proposition}[Weak Mordell--Weil]\label{mumford-prop-weak-mordell-weil}
\label{mumford-thm-weak-mordell-weil}
For every $n>1$, $X(K)/nX(K)$ is finite.
\source{mumford-abelian-varieties:page-0272}\uses{mumford-lem-fundamental-mordell-weil,mumford-prop-kummer-deduction}
\end{proposition}
\begin{proposition}[Height pairing]\label{mumford-prop-height-quadratic}
\label{mumford-prop-canonical-height}
There is a symmetric bilinear pairing $\langle\ ,\ \rangle:X(K)^2\to\mathbb R$
with $\langle x,x\rangle\ge0$ and with finitely many $x$ satisfying
$\langle x,x\rangle<C$ for every $C>0$.
\source{mumford-abelian-varieties:page-0272}\uses{mumford-lem-tate-height,mumford-prop-bounded-height-projective}
\end{proposition}
\begin{proposition}[Formal finite-generation criterion]\label{mumford-prop-formal-finite-generation}
\label{mumford-thm-mordell-weil-descent}
If an abelian group $\Gamma$ has finite $\Gamma/n\Gamma$ for every $n>1$ and
has a pairing with the preceding two properties, then $\Gamma$ is finitely generated.
\source{mumford-abelian-varieties:page-0273}
\lean{Mumford.finiteGeneration_of_finite_quotients_and_symmetric_pairing}
\leanok
\end{proposition}
\begin{proof}
Choose representatives $x_1,\ldots,x_s$ of $\Gamma/n\Gamma$. For some $C$,
\[
\langle x,x\rangle>C\Rightarrow\langle x-x_i,x-x_i\rangle<2\langle x,x\rangle.\tag{1}
\]
Indeed this follows from
$\langle x-x_i,x-x_i\rangle=\langle x,x\rangle-2\langle x,x_i\rangle+\langle x_i,x_i\rangle$
and Cauchy--Schwarz,
$\langle x,x_i\rangle\le\langle x_i,x_i\rangle^{1/2}\langle x,x\rangle^{1/2}$.
The finite set
$M=\{x_1,\ldots,x_s\}\cup\{x:\langle x,x\rangle<C\}$ generates. Otherwise choose
$x\notin\Gamma_0=\langle M\rangle$ of minimal norm. Then $x-x_i=ny$ for some
$x_i\in M$, and
\[
\langle y,y\rangle=n^{-2}\langle x-x_i,x-x_i\rangle<2n^{-2}\langle x,x\rangle<\langle x,x\rangle.
\]
Thus $y\in\Gamma_0$ and $x=ny+x_i\in\Gamma_0$, contradiction.

\end{proof}

\begin{lemma}[Fundamental lemma]\label{mumford-lem-fundamental-mordell-weil}
For $L=K(n_X^{-1}X(K))$, the composite of the fields obtained by adjoining
all $n$-division points of points of $X(K)$, $L/K$ is finite abelian.
\source{mumford-abelian-varieties:page-0274}
\uses{mumford-cor-division-unramified,mumford-lem-bounded-kummer-extensions}
\end{lemma}
\begin{proposition}[Kummer deduction]\label{mumford-prop-kummer-deduction}
For $G={\rm Gal}(L/K)$,
\[
X(K)/nX(K)\hookrightarrow{\rm Hom}(G,X_n),\qquad
f_x(s)=s(n^{-1}x)-n^{-1}x.
\]
\source{mumford-abelian-varieties:page-0274}\source{mumford-abelian-varieties:page-0275}
\end{proposition}
\begin{proof}
$f_x$ is independent of the division point since $X_n\subset X(K)$;
it is additive, and
$f_x=0\Longleftrightarrow n^{-1}x\in X(K)\Longleftrightarrow x\in nX(K)$.
Thus the map is injective and its target is finite.

\end{proof}

\begin{lemma}[Integral model]\label{mumford-lem-abelian-integral-model}
For a ring of integers $A$ of $K$, after shrinking $Y={\rm Spec}A_s$ there are
a projective $\widetilde X\to Y$, multiplication $\widetilde m$, and section
$\widetilde e$ whose generic fibre is $X$, whose closed fibres are abelian
varieties, and with $\widetilde X(Y)\simeq X(K)$.
\source{mumford-abelian-varieties:page-0275}
\end{lemma}
\begin{proof}[Outline of proof]
Present the variety and its finite diagram of morphisms by finitely many
equations, clear denominators, and shrink the base. Shrink again so all fibres
are smooth and the group diagrams remain valid. Finally take $A_s$ principal;
the projective embedding and
\[
\mathbb P^N_{\widetilde X}(Y)=\{(s_0,\ldots,s_N):s_i\in A_s,\ s_i\text{ coprime}\}/R
\]
show that every generic point extends to a $Y$-point. The omitted smoothness
and projective-point results are the stated standard inputs.
\notready
\end{proof}

\begin{corollary}[Etaleness of division points]\label{mumford-cor-division-etale-integral-model}
If $x\in\widetilde X(Y)$, then $n^{-1}(x)\to\operatorname{Spec}A_s$ is etale
where the residue characteristic does not divide $n$.
\source{mumford-abelian-varieties:page-0276}
\end{corollary}
\begin{proof}
Every component maps onto the base, and the fibre has $n^{2g}$ geometric
points, equal to the degree of the kernel of multiplication by $n$ in the
prime-to-characteristic case. Hence the morphism is etale.

\end{proof}
\begin{corollary}[Unramified division fields]\label{mumford-cor-division-unramified}
There is a finite set $E$ of prime ideals of $A$ such that for $x\in X(K)$ and
$y\in n^{-1}(x)$, $K(y)/K$ is unramified outside $E$.
\source{mumford-abelian-varieties:page-0277}\uses{mumford-cor-division-etale-integral-model}
\end{corollary}

\begin{lemma}[Bounded Kummer extensions]\label{mumford-lem-bounded-kummer-extensions}
The maximal abelian exponent-$n$ extension of $K$ unramified outside fixed $E$
is finite.
\source{mumford-abelian-varieties:page-0277}
\end{lemma}
\begin{proof}
For $F/K$ maximal and $H={\rm Gal}(F/K)$, the sequence
\[
1\to\mu_n\to\overline K^*\xrightarrow{n}\overline K^*\to1
\]
and Hilbert 90 give
\[
K^*/(K^*)^n\simeq{\rm Hom}(H,\mu_n).
\]
Thus the pairing
\[
H\times K^*/(K^*)^n\to\mu_n,\quad
(\sigma,\alpha(K^*)^n)\mapsto\sigma(\sqrt[n]{\alpha})/\sqrt[n]{\alpha}\tag{3}
\]
is nondegenerate, and Kummer theory gives $L=K(\sqrt[n]{B})$ for the
orthogonal subgroup $B$. Locally, unramifiedness outside $E$ is equivalent to
$v(a)\equiv0\pmod n$ for every $v\notin E$. Such elements form finitely many
 classes modulo $K^{*n}$ by finiteness of ideal classes and $E$-units.
\source{mumford-abelian-varieties:page-0278}

\end{proof}

\begin{proof}[Proof of the fundamental lemma]
The division field is abelian of exponent $n$: conjugates of a chosen
$n$-division point differ by elements of $X_n$. By the unramified-division
corollary it is unramified outside a fixed finite set $E$, and the bounded
Kummer extension lemma makes the maximal such extension finite.
\end{proof}

\section{Heights on projective space}\label{mumford-appendix-II-heights-source}\dcref{M:appII:II}
For normalized absolute values,
\[
\log|xy|_v=\log|x|_v+\log|y|_v,\quad
\log|x+y|_v\le\max(\log|x|_v,\log|y|_v)+c_v,
\]
where $c_v=\log2$ archimedean and $0$ otherwise, and
$\sum_vn_v\log|x|_v=0$ for $x\in K^*$.
\begin{lemma}[Projective height]\label{mumford-lem-projective-height}
\[
h(x_0,\ldots,x_n)=\frac1{[K:\mathbb Q]}\sum_vn_v\max_i\log|x_i|_v.\tag{6}
\]
This is well defined on $\mathbb P^n(K)$, invariant under scaling, nonnegative,
and independent of the field containing the coordinates.
\source{mumford-abelian-varieties:page-0279}
\end{lemma}
\begin{proof}
Scaling invariance follows from the product formula. Divide by a nonzero
coordinate to make one coordinate a unit; non-archimedean maxima are then
nonnegative. If $L\supset K$ and $w|v$, then
$K_v\otimes_KL=\bigoplus_{w|v}L_w$ and
$[L:K]n_v=\sum_{w|v}n_w$, which proves field independence.

\end{proof}
\begin{proposition}[Bounded height and degree]\label{mumford-prop-bounded-height-projective}
\label{mumford-lem-northcott-abelian}
For $C,d>0$, finitely many $x\in\mathbb P^n(\overline K)$ satisfy
$h(x)\le C$ and $[K(x):K]\le d$.
\source{mumford-abelian-varieties:page-0280}\source{mumford-abelian-varieties:page-0281}
\end{proposition}
\begin{proof}
Map a point to the coefficients of the norm form
${\rm Nm}(\sum_i x_iT_i)$. The fibres are finite because factorization into
conjugate linear factors is unique. The triangle inequality gives
\[
\max_i\log|x_i'|_v\le d\max_{i,v'}\log|x_i'|_{v'}+d_v,
\]
with $d_v=0$ non-archimedean, hence $h(X_0,\ldots,X_m)\le d'h(x)+d''$.
Bounded-height rational points are finite.

\end{proof}
\begin{proposition}[Equivalent coordinate heights]\label{mumford-prop-equivalent-projective-heights}
Heights $h_1,h_2$ from two coordinate systems satisfy $h_1\sim h_2$.
\source{mumford-abelian-varieties:page-0281}
\end{proposition}
\begin{proof}
For $(x'')=(x')A$, at archimedean places
\[
\max_i\log|x_i''|_v\le\max_i\log|x_i'|_v+\max_{i,j}\log|a_{ij}|_v+\log(n+1),
\]
and omit the last term non-archimedean. Thus $h_2\le h_1+C$; apply the same
argument to $A^{-1}$.

\end{proof}




\section{Heights associated with line bundles}
\label{mumford-appendix-II-heights-line-bundles}
\dcref{M:appII:II}

For a morphism $\varphi:X\to\mathbb P^n$ over $K$, put
$h_\varphi(x)=h(\varphi(x))$ on $X(\overline K)$.

\begin{proposition}[Height of a line bundle embedding]
\label{mumford-prop-morphism-height-equivalence}
Let $X$ be complete over $K$, and let $\varphi:X\to\mathbb P^k$ and
$\psi:X\to\mathbb P^l$ be $K$-morphisms. If
$\varphi^*\mathcal O(1)\simeq\psi^*\mathcal O(1)$, then
$h_\varphi\sim h_\psi$ on $X(\overline K)$.
\source{mumford-abelian-varieties:page-0282}
\end{proposition}
\begin{proof}
Put $L=\varphi^*\mathcal O(1)=\psi^*\mathcal O(1)$ and let
$\chi:X\to{\rm Proj}(S(\Gamma(X,L)))$ be the associated morphism. Then
$\chi^*\mathcal O(1)=L$, so it suffices by symmetry to prove
$h_\chi\sim h_\varphi$. Assume $\varphi(X)$ is not contained in a proper
linear subspace. Choose $(T_0,\ldots,T_k)$ from the pulled-back coordinate
sections and extend it to $(T_0,\ldots,T_n)$ in $\Gamma(X,L)$. For
$\chi(x)=(x_0,\ldots,x_n)$ and $\varphi(x)=(x_0,\ldots,x_k)$,
$h_\varphi\le h_\chi$.

The image $\chi(X)$ is closed. If $I$ is its homogeneous ideal and
$R=K[T_0,\ldots,T_n]/I$, the first $k+1$ sections have no common zero, so
some $q>0$ and forms $F_{ij}$ of degree $q-1$ satisfy
\[
 T_i^q=\sum_{j=0}^kF_{ij}(T_0,\ldots,T_n)T_j,
 \qquad i=1,\ldots,n-k. \tag{7}
\]
Hence
$x_i^q=\sum_{j=0}^kF_{ij}(x_0,\ldots,x_n)x_j$. Applying the height estimate
gives
\[
 q\log|x_i|_v\le(q-1)\max_{j\le n}\log|x_j|_v+
 \max_{j\le n}\log|x_j|_v+C_v,
\]
where $C_v$ is nonzero at only finitely many places. Thus
$\max_{i\le n}\log|x_i|_v\le\max_{j\le k}\log|x_j|_v+C_v$, and
$h_\chi\le h_\varphi+C$.

\end{proof}


\begin{theorem}[Weil height theorem]
\label{mumford-thm-weil-height-line-bundle}
For every projective variety $X/K$ and $L\in{\rm Pic}X$, there is a height
$h_L$ on $X(\overline K)$, unique up to equivalence, such that
\begin{enumerate}
\item $h_{L_1\otimes L_2}\sim h_{L_1}+h_{L_2}$;
\item for $X=\mathbb P^n$, $h_{\mathcal O(1)}$ is the projective height;
\item for $\varphi:X\to Y$, $h_{\varphi^*L}\sim h_L\circ\varphi$.
\end{enumerate}
\source{mumford-abelian-varieties:page-0283}
\source{mumford-abelian-varieties:page-0284}
\uses{mumford-prop-morphism-height-equivalence,mumford-lem-projective-height}
\end{theorem}
\begin{proof}
Uniqueness follows because ${\rm Pic}X$ is generated by very ample bundles,
whose heights have the required properties by the proposition. For
$L_1=\varphi^*\mathcal O(1)$ and $L_2=\psi^*\mathcal O(1)$, use the Segre map
$\sigma:\mathbb P^k\times\mathbb P^l\to\mathbb P^N$:
\[
 ((x_0,\ldots,x_k),(y_0,\ldots,y_l))\mapsto(\ldots,x_iy_j,\ldots),
\]
with
$\sigma^*\mathcal O(1)=p_1^*\mathcal O(1)\otimes p_2^*\mathcal O(1)$.
The composite $\chi=\sigma\circ(\varphi,\psi)$ represents $L_1\otimes L_2$,
and
\[
 \max_{i,j}\log|x_iy_j|_v=\max_i\log|x_i|_v+\max_j\log|y_j|_v,
\]
so $h_\chi\sim h_\varphi+h_\psi$. For arbitrary $L$, write
$L=L_1\otimes L_2^{-1}$ with $L_i$ very ample and define
$h_L=h_{L_1}-h_{L_2}$. The preceding result makes this independent up to
equivalence and proves (a),(b). For (c), it suffices to use generators
$L=\psi^*\mathcal O(1)$; then both sides are the height of
$\psi\circ\varphi$.

\end{proof}


\begin{lemma}[Approximate quadratic functions]
\label{mumford-lem-approximate-quadratic}
If $h:\Gamma\to\mathbb R$ on an abelian group satisfies
\[
h(x_1+x_2+x_3)-\sum_{i<j}h(x_i+x_j)+\sum_i h(x_i)\sim0,\tag{8}
\]
then there are unique symmetric bilinear $b:\Gamma^2\to\mathbb R$ and
homomorphism $l:\Gamma\to\mathbb R$ such that
\[
h(x)\sim\widehat h(x)=\frac12b(x,x)+l(x).
\]
\source{mumford-abelian-varieties:page-0284}
\source{mumford-abelian-varieties:page-0285}
\end{lemma}
\begin{proof}
Put $\beta(x_1,x_2)=h(x_1+x_2)-h(x_1)-h(x_2)$. It is symmetric and
approximately additive:
\[
\beta(x_1+x_2,x_3)-\beta(x_1,x_3)-\beta(x_2,x_3)\sim0.\tag{9}
\]
Define
\[
b(x_1,x_2)=\lim_{n\to\infty}4^{-n}\beta(2^nx_1,2^nx_2).
\]
Indeed, with $\theta_n\sim0$,
\[
4^{-(n+1)}\beta(2^{n+1}x_1,2^{n+1}x_2)=
4^{-n}\beta(2^nx_1,2^nx_2)+4^{-(n+1)}\theta_n,
\]
so
\[
4^{-N}\beta(2^Nx_1,2^Nx_2)=\beta(x_1,x_2)+
\sum_{n=0}^{N-1}4^{-(n+1)}\theta_n.
\]
Equation (9) gives bilinearity of $b$. Set
$\lambda(x)=h(x)-\frac12b(x,x)$. Then
$\lambda(x_1+x_2)-\lambda(x_1)-\lambda(x_2)\sim0$, and the same averaging gives
\[
l(x)=\lim_n2^{-n}\lambda(2^nx),
\]
a homomorphism. Thus $\widehat h\sim\frac12b+l$, and uniqueness is immediate.

\end{proof}


\begin{lemma}[Tate height]
\label{mumford-lem-tate-height}
\label{mumford-lem-height-parallelogram}
For an abelian variety $X/K$ and $L\in{\rm Pic}X$, the Weil height $h_L$
satisfies (8). Hence $b_L,l_L$ and the Tate height $\widehat h_L$ are uniquely
defined.
\source{mumford-abelian-varieties:page-0285}
\source{mumford-abelian-varieties:page-0286}
\uses{mumford-thm-weil-height-line-bundle,mumford-lem-approximate-quadratic}
\end{lemma}
\begin{proof}
Apply the theorem of the cube to the projections from $X^3$; the resulting
line-bundle identity is
\[
\left(\sum_{i=1}^3p_i\right)^*L\otimes
\bigotimes_{i<j}(p_i+p_j)^*L^{-1}\otimes\bigotimes_{i=1}^3p_i^*L\simeq L.
\]
Taking heights at $(x_1,x_2,x_3)$ and using the Weil height properties yields
(8).

\end{proof}


\begin{remark}[Functoriality and symmetric bundles]
\label{mumford-rem-tate-height-functoriality}
For $\varphi:X\to Y$ and $L\in{\rm Pic}Y$,
$\widehat h_{\varphi^*L}=\widehat h_L\circ\varphi$ and
$b_{\varphi^*L}=b_L\circ\varphi$, $l_{\varphi^*L}=l_L\circ\varphi$.
For $L^{-1}$, $b_{L^{-1}}=-b_L$ and $l_{L^{-1}}=-l_L$. If $L$ is symmetric,
$l_L=0$ and $\widehat h_L(x)=\frac12b_L(x,x)$.
\source{mumford-abelian-varieties:page-0286}
\end{remark}

\begin{proof}[Proof of Proposition 3 and Mordell--Weil]
Choose a symmetric very ample $L$ on $X$ and put
$\langle x,y\rangle=b_L(x,y)$. Then $\langle x,x\rangle\ge0$: otherwise
$\widehat h_L(nx)=\frac12n^2\langle x,x\rangle\to-\infty$, contradicting
$\widehat h_L\sim h_L$ and the existence of a nonnegative representative of
the height class. Proposition 4 implies that the set of $x\in X(K)$ with
$h_L(x)\le c$ is finite, hence the same holds for
$\{x:\langle x,x\rangle\le C\}$. Proposition 2 follows, and the formal
finite-generation criterion proves the Mordell--Weil theorem.
\source{mumford-abelian-varieties:page-0286}
\uses{mumford-lem-tate-height,mumford-prop-bounded-height-projective,mumford-prop-formal-finite-generation}
\end{proof}
